INSERT INTO languages (code, name, short_label, is_default) VALUES ('ru', 'Русский', 'RU', TRUE);
INSERT INTO languages (code, name, short_label, is_default) VALUES ('kk', 'Қазақша', 'ҚАЗ', FALSE);
INSERT INTO legal_sources (id, code, is_active) VALUES ('pdd-534', 'V2300033003', TRUE);
INSERT INTO legal_source_translations (source_id, lang, title, url) VALUES ('pdd-534', 'ru', 'Правила дорожного движения Республики Казахстан, утверждённые приказом Министра внутренних дел РК от 30 июня 2023 года № 534 (с изменениями и дополнениями)', 'https://adilet.zan.kz/rus/docs/V2300033003');
INSERT INTO legal_source_translations (source_id, lang, title, url) VALUES ('pdd-534', 'kk', 'Қазақстан Республикасы Ішкі істер министрінің 2023 жылғы 30 маусымдағы № 534 бұйрығымен бекітілген Жол қозғалысы ережелері (өзгерістерімен және толықтыруларымен)', 'https://adilet.zan.kz/kaz/docs/V2300033003');
INSERT INTO legal_sources (id, code, is_active) VALUES ('law-194', 'Z1400000194', TRUE);
INSERT INTO legal_source_translations (source_id, lang, title, url) VALUES ('law-194', 'ru', 'Закон Республики Казахстан от 17 апреля 2014 года № 194-V «О дорожном движении»', 'https://adilet.zan.kz/rus/docs/Z1400000194');
INSERT INTO legal_source_translations (source_id, lang, title, url) VALUES ('law-194', 'kk', '«Жол жүрісі туралы» Қазақстан Республикасының 2014 жылғы 17 сәуірдегі № 194-V Заңы', 'https://adilet.zan.kz/kaz/docs/Z1400000194');
INSERT INTO topics (id, sort_order, icon) VALUES ('general', 1, 'book');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('general', 'ru', 'Общие положения', 'Основные термины, сторона движения и порядок приоритета сигналов.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('general', 'kk', 'Жалпы ережелер', 'Негізгі терминдер, қозғалыс жағы және сигналдардың басымдық тәртібі.');
INSERT INTO topics (id, sort_order, icon) VALUES ('driver', 2, 'wheel');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('driver', 'ru', 'Обязанности водителя', 'Документы, ремни безопасности, телефон, действия при ДТП.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('driver', 'kk', 'Жүргізушінің міндеттері', 'Құжаттар, қауіпсіздік белдіктері, телефон, ЖКО кезіндегі әрекеттер.');
INSERT INTO topics (id, sort_order, icon) VALUES ('signs', 3, 'sign');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('signs', 'ru', 'Дорожные знаки', 'Группы знаков и значение наиболее важных из них.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('signs', 'kk', 'Жол белгілері', 'Белгілер топтары және ең маңыздыларының мағынасы.');
INSERT INTO topics (id, sort_order, icon) VALUES ('markings', 4, 'lines');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('markings', 'ru', 'Дорожная разметка', 'Сплошные и прерывистые линии, стоп-линия, «зебра».');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('markings', 'kk', 'Жол таңбасы', 'Тұтас және үзік сызықтар, тоқтау сызығы, «зебра».');
INSERT INTO topics (id, sort_order, icon) VALUES ('signals', 5, 'light');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('signals', 'ru', 'Светофоры и регулировщик', 'Значение сигналов светофора, дополнительные секции, жесты регулировщика.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('signals', 'kk', 'Бағдаршамдар және реттеуші', 'Бағдаршам сигналдарының мағынасы, қосымша секциялар, реттеушінің ымдары.');
INSERT INTO topics (id, sort_order, icon) VALUES ('intersections', 6, 'cross');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('intersections', 'ru', 'Проезд перекрёстков', 'Регулируемые и нерегулируемые перекрёстки, «помеха справа», поворот налево.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('intersections', 'kk', 'Жол қиылыстарынан өту', 'Реттелетін және реттелмейтін қиылыстар, «оң жақтан кедергі», солға бұрылу.');
INSERT INTO topics (id, sort_order, icon) VALUES ('speed', 7, 'gauge');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('speed', 'ru', 'Скорость движения', 'Ограничения скорости в населённых пунктах и вне их.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('speed', 'kk', 'Қозғалыс жылдамдығы', 'Елді мекендерде және олардан тыс жерлердегі жылдамдық шектеулері.');
INSERT INTO topics (id, sort_order, icon) VALUES ('overtaking', 8, 'overtake');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('overtaking', 'ru', 'Обгон и встречный разъезд', 'Когда обгон разрешён, где он запрещён и обязанности обгоняемого.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('overtaking', 'kk', 'Басып озу және қарсы жолмен айырылысу', 'Басып озуға қашан рұқсат етіледі, қай жерде тыйым салынады және озылатын жүргізушінің міндеттері.');
INSERT INTO topics (id, sort_order, icon) VALUES ('stopping', 9, 'parking');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('stopping', 'ru', 'Остановка и стоянка', 'Где можно и где нельзя останавливаться, расстояния до объектов.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('stopping', 'kk', 'Тоқтау және тұрақ', 'Қай жерде тоқтауға болады және болмайды, объектілерге дейінгі қашықтықтар.');
INSERT INTO topics (id, sort_order, icon) VALUES ('pedestrians', 10, 'walker');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('pedestrians', 'ru', 'Пешеходы и переходы', 'Обязанности пешеходов и водителей у пешеходных переходов.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('pedestrians', 'kk', 'Жаяу жүргіншілер және өткелдер', 'Жаяу жүргіншілердің және өткелдер маңындағы жүргізушілердің міндеттері.');
INSERT INTO topics (id, sort_order, icon) VALUES ('passengers', 11, 'seat');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('passengers', 'ru', 'Перевозка пассажиров', 'Посадка и высадка, перевозка детей, обязанности пассажиров.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('passengers', 'kk', 'Жолаушыларды тасымалдау', 'Отырғызу және түсіру, балаларды тасымалдау, жолаушылардың міндеттері.');
INSERT INTO topics (id, sort_order, icon) VALUES ('safety', 12, 'aid');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('safety', 'ru', 'Первая помощь и безопасность', 'Аварийная сигнализация, действия на месте ДТП, базовая первая помощь.');
INSERT INTO topic_translations (topic_id, lang, title, description) VALUES ('safety', 'kk', 'Алғашқы көмек және қауіпсіздік', 'Авариялық дабыл, ЖКО орнындағы әрекеттер, алғашқы көмектің негіздері.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('general', 'general', 'pdd-534', 1);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('general', 'ru', 'Общие положения', 'ПДД РК, раздел 1 «Общие положения»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('general', 'kk', 'Жалпы ережелер', 'ЖҚЕ, 1-бөлім «Жалпы ережелер»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('general-1', 'general', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-1', 'ru', 'Правила дорожного движения устанавливают единый порядок дорожного движения на всей территории Республики Казахстан. Их основой служит Закон РК «О дорожном движении».');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-1', 'kk', 'Жол қозғалысы ережелері Қазақстан Республикасының бүкіл аумағында жол қозғалысының бірыңғай тәртібін белгілейді. Олардың негізі — «Жол жүрісі туралы» ҚР Заңы.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('general-2', 'general', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-2', 'ru', 'На дорогах Казахстана установлено правостороннее движение транспортных средств.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-2', 'kk', 'Қазақстан жолдарында көлік құралдарының оң жақты қозғалысы белгіленген.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('general-3', 'general', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-3', 'ru', 'Участники дорожного движения обязаны знать и соблюдать Правила, требования сигналов светофоров, знаков и разметки, а также выполнять распоряжения регулировщиков. Их действия не должны создавать опасности для движения и причинять вред.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-3', 'kk', 'Жол қозғалысына қатысушылар Ережелерді, бағдаршам сигналдарының, белгілер мен жол таңбасының талаптарын білуге және сақтауға, сондай-ақ реттеушілердің нұсқауларын орындауға міндетті. Олардың әрекеттері қозғалысқа қауіп төндірмеуі және зиян келтірмеуі тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('general-4', 'general', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-4', 'ru', '«Уступить дорогу» — требование, означающее, что участник движения не должен начинать, возобновлять или продолжать движение, осуществлять какой-либо манёвр, если это может вынудить других участников, имеющих преимущество, изменить направление движения или скорость.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-4', 'kk', '«Жол беру» — қозғалысқа қатысушы, егер бұл басымдығы бар басқа қатысушыларды қозғалыс бағытын немесе жылдамдығын өзгертуге мәжбүр етуі мүмкін болса, қозғалысты бастамауы, қайта бастамауы немесе жалғастырмауы, қандай да бір маневр жасамауы тиіс екенін білдіретін талап.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('general-5', 'general', 5, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-5', 'ru', 'Порядок приоритета: сигналы регулировщика имеют приоритет над сигналами светофора и требованиями знаков и разметки; сигналы светофора (кроме мигающего жёлтого) — над знаками приоритета; временные знаки — над постоянными знаками и разметкой.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-5', 'kk', 'Басымдық тәртібі: реттеушінің сигналдары бағдаршам сигналдарынан, белгілер мен таңба талаптарынан басым; бағдаршам сигналдары (жыпылықтайтын сарыдан басқа) басымдық белгілерінен басым; уақытша белгілер тұрақты белгілер мен таңбадан басым.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('general-6', 'general', 6, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-6', 'ru', 'Недостаточная видимость — видимость дороги менее 300 м в условиях тумана, дождя, снегопада и т. п., а также в сумерки.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('general-6', 'kk', 'Жеткіліксіз көріну — тұман, жаңбыр, қар жауған және т.б. жағдайларда, сондай-ақ ымыртта жолдың 300 м-ден кем көрінуі.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('driver', 'driver', 'pdd-534', 2);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('driver', 'ru', 'Обязанности водителя', 'ПДД РК, раздел 2 «Общие обязанности водителей»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('driver', 'kk', 'Жүргізушінің міндеттері', 'ЖҚЕ, 2-бөлім «Жүргізушілердің жалпы міндеттері»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('driver-1', 'driver', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-1', 'ru', 'Водитель обязан иметь водительское удостоверение на право управления транспортным средством соответствующей категории и регистрационный документ на транспортное средство и предъявлять их по требованию сотрудника полиции (в том числе в электронном виде — в случаях, предусмотренных законодательством).');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-1', 'kk', 'Жүргізушіде тиісті санаттағы көлік құралын басқару құқығына жүргізуші куәлігі және көлік құралының тіркеу құжаты болуға және полиция қызметкерінің талабы бойынша оларды көрсетуге (заңнамада көзделген жағдайларда — электрондық түрде де) міндетті.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('driver-2', 'driver', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-2', 'ru', 'При движении на транспортном средстве, оборудованном ремнями безопасности, водитель должен быть пристёгнут и не перевозить непристёгнутых пассажиров. Водитель и пассажиры мотоцикла должны быть в застёгнутом мотошлеме.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-2', 'kk', 'Қауіпсіздік белдіктерімен жабдықталған көлік құралымен жүргенде жүргізуші белдікпен байлануы және байланбаған жолаушыларды тасымалдамауы тиіс. Мотоцикл жүргізушісі мен жолаушылары түймеленген мотошлемде болуы тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('driver-3', 'driver', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-3', 'ru', 'Водителю запрещается управлять транспортным средством в состоянии алкогольного, наркотического или токсикоманического опьянения, под воздействием лекарств, ухудшающих реакцию и внимание, а также в болезненном или утомлённом состоянии.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-3', 'kk', 'Жүргізушіге алкогольдік, есірткілік немесе уытқұмарлық мас күйде, реакция мен зейінді нашарлататын дәрілердің әсерімен, сондай-ақ ауру немесе шаршаған күйде көлік құралын басқаруға тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('driver-4', 'driver', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-4', 'ru', 'Во время движения водителю запрещается пользоваться телефоном, держа его в руке. Разговор допускается только с использованием технических устройств, позволяющих вести переговоры без использования рук.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-4', 'kk', 'Қозғалыс кезінде жүргізушіге телефонды қолмен ұстап пайдалануға тыйым салынады. Сөйлесуге тек қолды пайдаланбай сөйлесуге мүмкіндік беретін техникалық құрылғылар арқылы ғана рұқсат етіледі.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('driver-5', 'driver', 5, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-5', 'ru', 'Запрещается передавать управление транспортным средством лицам, не имеющим при себе водительского удостоверения соответствующей категории, кроме случаев обучения вождению в установленном порядке.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-5', 'kk', 'Белгіленген тәртіппен жүргізуді үйрету жағдайларын қоспағанда, көлік құралын басқаруды жанында тиісті санаттағы жүргізуші куәлігі жоқ адамдарға беруге тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('driver-6', 'driver', 6, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-6', 'ru', 'Водитель, причастный к дорожно-транспортному происшествию, обязан немедленно остановиться, включить аварийную сигнализацию, выставить знак аварийной остановки, не перемещать предметы, имеющие отношение к происшествию, принять меры для оказания первой помощи пострадавшим и сообщить о случившемся в полицию.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('driver-6', 'kk', 'Жол-көлік оқиғасына қатысы бар жүргізуші дереу тоқтауға, авариялық дабылды қосуға, авариялық тоқтау белгісін қоюға, оқиғаға қатысты заттарды орнынан жылжытпауға, зардап шеккендерге алғашқы көмек көрсету шараларын қабылдауға және болған жағдай туралы полицияға хабарлауға міндетті.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('signs', 'signs', 'pdd-534', 3);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('signs', 'ru', 'Дорожные знаки', 'ПДД РК, приложение «Дорожные знаки»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('signs', 'kk', 'Жол белгілері', 'ЖҚЕ, «Жол белгілері» қосымшасы');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signs-1', 'signs', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-1', 'ru', 'Знаки делятся на группы: предупреждающие, знаки приоритета, запрещающие, предписывающие, информационно-указательные, знаки сервиса и знаки дополнительной информации (таблички).');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-1', 'kk', 'Белгілер топтарға бөлінеді: ескерту, басымдық, тыйым салу, нұсқама, ақпараттық-нұсқағыш, сервис белгілері және қосымша ақпарат белгілері (тақтайшалар).');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signs-2', 'signs', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-2', 'ru', 'Предупреждающие знаки (треугольник с красной каймой) информируют о приближении к опасному участку, движение по которому требует мер, соответствующих обстановке. Например, знак «Дети» предупреждает о возможном появлении детей на проезжей части.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-2', 'kk', 'Ескерту белгілері (қызыл жиекті үшбұрыш) жағдайға сәйкес шаралар қолдануды талап ететін қауіпті учаскеге жақындағаны туралы хабарлайды. Мысалы, «Балалар» белгісі жүру бөлігінде балалардың пайда болуы мүмкін екенін ескертеді.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signs-3', 'signs', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-3', 'ru', 'Знаки приоритета устанавливают очерёдность проезда: «Главная дорога» (жёлтый ромб) даёт преимущество, «Уступите дорогу» (перевёрнутый треугольник) обязывает уступить, «Движение без остановки запрещено» (STOP) требует остановиться у стоп-линии, а при её отсутствии — у края пересекаемой проезжей части, и уступить дорогу.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-3', 'kk', 'Басымдық белгілері өту кезектілігін белгілейді: «Басты жол» (сары ромб) артықшылық береді, «Жол беріңіз» (төңкерілген үшбұрыш) жол беруге міндеттейді, «Тоқтамай жүруге тыйым салынады» (STOP) тоқтау сызығының алдында, ол болмаса — қиылысатын жүру бөлігінің шетінде тоқтап, жол беруді талап етеді.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signs-4', 'signs', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-4', 'ru', 'Запрещающие знаки (круг с красной каймой) вводят или отменяют ограничения. Знак «Обгон запрещён» запрещает обгон всех транспортных средств, кроме тихоходных, гужевых повозок, велосипедов, мопедов и двухколёсных мотоциклов без коляски. Знак «Остановка запрещена» запрещает и остановку, и стоянку; «Стоянка запрещена» — только стоянку.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-4', 'kk', 'Тыйым салу белгілері (қызыл жиекті шеңбер) шектеулер енгізеді немесе алып тастайды. «Басып озуға тыйым салынады» белгісі баяу жүретін көлік құралдарынан, ат арбаларынан, велосипедтерден, мопедтерден және бүйірлі арбасыз екі дөңгелекті мотоциклдерден басқа барлық көлік құралдарын басып озуға тыйым салады. «Тоқтауға тыйым салынады» белгісі тоқтауға да, тұраққа да тыйым салады; «Тұраққа тыйым салынады» — тек тұраққа.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signs-5', 'signs', 5, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-5', 'ru', 'Предписывающие знаки (синий круг) обязывают двигаться в указанных направлениях или устанавливают минимальную скорость. Информационно-указательные знаки вводят и отменяют режимы движения (например, «Жилая зона», «Пешеходный переход»).');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-5', 'kk', 'Нұсқама белгілері (көк шеңбер) көрсетілген бағыттарда жүруге міндеттейді немесе ең аз жылдамдықты белгілейді. Ақпараттық-нұсқағыш белгілер қозғалыс режимдерін енгізеді және алып тастайды (мысалы, «Тұрғын аймақ», «Жаяу жүргіншілер өткелі»).');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signs-6', 'signs', 6, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-6', 'ru', 'Временные знаки, установленные на переносных стойках или в местах дорожных работ, имеют приоритет над постоянными знаками и разметкой.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signs-6', 'kk', 'Жылжымалы тіректерде немесе жол жұмыстары орындарында орнатылған уақытша белгілер тұрақты белгілер мен таңбадан басым болады.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('markings', 'markings', 'pdd-534', 4);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('markings', 'ru', 'Дорожная разметка', 'ПДД РК, приложение «Дорожная разметка»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('markings', 'kk', 'Жол таңбасы', 'ЖҚЕ, «Жол таңбасы» қосымшасы');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('markings-1', 'markings', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-1', 'ru', 'Сплошная линия (1.1) и двойная сплошная (1.3) разделяют транспортные потоки; пересекать их запрещается.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-1', 'kk', 'Тұтас сызық (1.1) және қос тұтас сызық (1.3) көлік ағындарын бөледі; оларды қиып өтуге тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('markings-2', 'markings', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-2', 'ru', 'Прерывистую линию (1.5) разрешается пересекать с любой стороны, если манёвр безопасен и не запрещён другими требованиями Правил. Линия приближения (1.6) предупреждает о приближении к сплошной линии.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-2', 'kk', 'Үзік сызықты (1.5), егер маневр қауіпсіз болса және Ережелердің басқа талаптарымен тыйым салынбаса, кез келген жақтан қиып өтуге рұқсат етіледі. Жақындау сызығы (1.6) тұтас сызыққа жақындағанын ескертеді.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('markings-3', 'markings', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-3', 'ru', 'Стоп-линия (1.12) указывает место остановки при запрещающем сигнале светофора или регулировщика либо при наличии знака «Движение без остановки запрещено». Разметка «зебра» (1.14) обозначает пешеходный переход.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-3', 'kk', 'Тоқтау сызығы (1.12) бағдаршамның немесе реттеушінің тыйым салатын сигналы кезінде немесе «Тоқтамай жүруге тыйым салынады» белгісі болғанда тоқтайтын орынды көрсетеді. «Зебра» таңбасы (1.14) жаяу жүргіншілер өткелін білдіреді.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('markings-4', 'markings', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-4', 'ru', 'Если значения временных дорожных знаков и линий разметки противоречат друг другу, водители должны руководствоваться знаками.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('markings-4', 'kk', 'Егер уақытша жол белгілері мен таңба сызықтарының мағыналары бір-біріне қайшы келсе, жүргізушілер белгілерді басшылыққа алуы тиіс.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('signals', 'signals', 'pdd-534', 5);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('signals', 'ru', 'Светофоры и регулировщик', 'ПДД РК, раздел 6 «Сигналы светофора и регулировщика»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('signals', 'kk', 'Бағдаршамдар және реттеуші', 'ЖҚЕ, 6-бөлім «Бағдаршам мен реттеуші сигналдары»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signals-1', 'signals', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-1', 'ru', 'Зелёный сигнал разрешает движение; зелёный мигающий разрешает движение и информирует, что время его действия истекает и вскоре будет включён запрещающий сигнал.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-1', 'kk', 'Жасыл сигнал қозғалысқа рұқсат береді; жыпылықтайтын жасыл қозғалысқа рұқсат береді және оның әрекет ету уақыты аяқталып келе жатқанын, көп ұзамай тыйым салатын сигнал қосылатынын хабарлайды.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signals-2', 'signals', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-2', 'ru', 'Жёлтый сигнал запрещает движение и предупреждает о смене сигналов. Водителям, которые при включении жёлтого сигнала не могут остановиться, не прибегая к экстренному торможению, разрешается дальнейшее движение.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-2', 'kk', 'Сары сигнал қозғалысқа тыйым салады және сигналдардың ауысатынын ескертеді. Сары сигнал қосылғанда шұғыл тежеуге жүгінбей тоқтай алмайтын жүргізушілерге әрі қарай жүруге рұқсат етіледі.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signals-3', 'signals', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-3', 'ru', 'Жёлтый мигающий сигнал разрешает движение и информирует о наличии нерегулируемого перекрёстка или пешеходного перехода, предупреждает об опасности.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-3', 'kk', 'Жыпылықтайтын сары сигнал қозғалысқа рұқсат береді және реттелмейтін қиылыстың немесе жаяу жүргіншілер өткелінің бар екенін хабарлайды, қауіп туралы ескертеді.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signals-4', 'signals', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-4', 'ru', 'Красный сигнал, в том числе мигающий, запрещает движение. Сочетание красного и жёлтого сигналов запрещает движение и информирует о предстоящем включении зелёного.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-4', 'kk', 'Қызыл сигнал, соның ішінде жыпылықтайтыны да, қозғалысқа тыйым салады. Қызыл мен сары сигналдардың қосарлануы қозғалысқа тыйым салады және жасыл сигналдың қосылатынын хабарлайды.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signals-5', 'signals', 5, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-5', 'ru', 'Зелёная стрелка в дополнительной секции разрешает движение в указанном направлении при включённом основном сигнале любого цвета. Двигаясь по ней, водитель должен уступить дорогу транспортным средствам, движущимся с других направлений.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-5', 'kk', 'Қосымша секциядағы жасыл бағдарше негізгі сигналдың кез келген түсі жанып тұрғанда көрсетілген бағытта қозғалуға рұқсат береді. Ол бойынша жүргенде жүргізуші басқа бағыттардан келе жатқан көлік құралдарына жол беруі тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('signals-6', 'signals', 6, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-6', 'ru', 'Если сигналы регулировщика противоречат сигналам светофора, знакам или разметке, водители должны выполнять требования регулировщика.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('signals-6', 'kk', 'Егер реттеушінің сигналдары бағдаршам сигналдарына, белгілерге немесе таңбаға қайшы келсе, жүргізушілер реттеушінің талаптарын орындауы тиіс.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('intersections', 'intersections', 'pdd-534', 6);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('intersections', 'ru', 'Проезд перекрёстков', 'ПДД РК, раздел 13 «Проезд перекрёстков»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('intersections', 'kk', 'Жол қиылыстарынан өту', 'ЖҚЕ, 13-бөлім «Жол қиылыстарынан өту»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('intersections-1', 'intersections', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-1', 'ru', 'При повороте направо или налево водитель обязан уступить дорогу пешеходам и велосипедистам, пересекающим проезжую часть дороги, на которую он поворачивает.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-1', 'kk', 'Оңға немесе солға бұрылғанда жүргізуші өзі бұрылатын жолдың жүру бөлігін кесіп өтіп жатқан жаяу жүргіншілер мен велосипедшілерге жол беруге міндетті.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('intersections-2', 'intersections', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-2', 'ru', 'Запрещается выезжать на перекрёсток, если впереди образовался затор, который вынудит водителя остановиться на перекрёстке и создать препятствие для движения в поперечном направлении.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-2', 'kk', 'Егер алда кептеліс пайда болып, ол жүргізушіні қиылыста тоқтауға және көлденең бағыттағы қозғалысқа кедергі келтіруге мәжбүр ететін болса, қиылысқа шығуға тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('intersections-3', 'intersections', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-3', 'ru', 'На регулируемом перекрёстке при повороте налево или развороте по зелёному сигналу водитель безрельсового транспортного средства должен уступить дорогу транспортным средствам, движущимся со встречного направления прямо или направо.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-3', 'kk', 'Реттелетін қиылыста жасыл сигнал бойынша солға бұрылғанда немесе кері бұрылғанда рельссіз көлік құралының жүргізушісі қарсы бағыттан тура немесе оңға жүріп келе жатқан көлік құралдарына жол беруі тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('intersections-4', 'intersections', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-4', 'ru', 'На нерегулируемом перекрёстке неравнозначных дорог водитель, движущийся по второстепенной дороге, должен уступить дорогу транспортным средствам, приближающимся по главной, независимо от направления их дальнейшего движения.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-4', 'kk', 'Тең емес жолдардың реттелмейтін қиылысында қосалқы жолмен келе жатқан жүргізуші басты жолмен жақындап келе жатқан көлік құралдарына, олардың әрі қарай қозғалу бағытына қарамастан, жол беруі тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('intersections-5', 'intersections', 5, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-5', 'ru', 'На перекрёстке равнозначных дорог водитель безрельсового транспортного средства обязан уступить дорогу транспортным средствам, приближающимся справа («помеха справа»). Этим же правилом руководствуются между собой водители трамваев.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('intersections-5', 'kk', 'Тең маңызды жолдардың қиылысында рельссіз көлік құралының жүргізушісі оң жақтан жақындап келе жатқан көлік құралдарына жол беруге міндетті («оң жақтан кедергі»). Трамвай жүргізушілері де өзара осы ережені басшылыққа алады.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('speed', 'speed', 'pdd-534', 7);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('speed', 'ru', 'Скорость движения', 'ПДД РК, раздел 10 «Скорость движения»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('speed', 'kk', 'Қозғалыс жылдамдығы', 'ЖҚЕ, 10-бөлім «Қозғалыс жылдамдығы»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('speed-1', 'speed', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-1', 'ru', 'Водитель должен вести транспортное средство со скоростью, не превышающей установленного ограничения, учитывая интенсивность движения, особенности и состояние транспортного средства и груза, дорожные и метеорологические условия, видимость в направлении движения.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-1', 'kk', 'Жүргізуші көлік құралын белгіленген шектеуден аспайтын жылдамдықпен, қозғалыс қарқындылығын, көлік құралы мен жүктің ерекшеліктері мен жай-күйін, жол және ауа райы жағдайларын, қозғалыс бағытындағы көрінуді ескере отырып жүргізуі тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('speed-2', 'speed', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-2', 'ru', 'В населённых пунктах разрешается движение со скоростью не более 60 км/ч, если иной режим не установлен дорожными знаками. В жилых зонах и на дворовых территориях — не более 20 км/ч.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-2', 'kk', 'Елді мекендерде, егер жол белгілерімен өзге режим белгіленбесе, сағатына 60 км-ден аспайтын жылдамдықпен жүруге рұқсат етіледі. Тұрғын аймақтарда және аула аумақтарында — сағатына 20 км-ден аспайды.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('speed-3', 'speed', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-3', 'ru', 'Вне населённых пунктов легковым автомобилям и мотоциклам разрешается движение на автомагистралях со скоростью не более 140 км/ч, на остальных дорогах — не более 110 км/ч, если знаками не установлено меньшее ограничение. Для других категорий транспортных средств установлены более низкие ограничения.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-3', 'kk', 'Елді мекендерден тыс жерлерде жеңіл автомобильдер мен мотоциклдерге, егер белгілермен неғұрлым төмен шектеу белгіленбесе, автомагистральдарда сағатына 140 км-ден, қалған жолдарда сағатына 110 км-ден аспайтын жылдамдықпен жүруге рұқсат етіледі. Көлік құралдарының басқа санаттары үшін неғұрлым төмен шектеулер белгіленген.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('speed-4', 'speed', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-4', 'ru', 'Водителю запрещается превышать максимальную скорость, определённую технической характеристикой транспортного средства, создавать помехи другим транспортным средствам, двигаясь без необходимости со слишком малой скоростью, и резко тормозить, если это не требуется для предотвращения ДТП.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('speed-4', 'kk', 'Жүргізушіге көлік құралының техникалық сипаттамасымен анықталған ең жоғары жылдамдықтан асыруға, қажетсіз тым төмен жылдамдықпен жүріп басқа көлік құралдарына кедергі келтіруге және ЖКО-ның алдын алу үшін қажет болмаса, күрт тежеуге тыйым салынады.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('overtaking', 'overtaking', 'pdd-534', 8);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('overtaking', 'ru', 'Обгон и встречный разъезд', 'ПДД РК, раздел 11 «Обгон, встречный разъезд»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('overtaking', 'kk', 'Басып озу және қарсы жолмен айырылысу', 'ЖҚЕ, 11-бөлім «Басып озу, қарсы жолмен айырылысу»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('overtaking-1', 'overtaking', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('overtaking-1', 'ru', 'Прежде чем начать обгон, водитель обязан убедиться, что полоса, на которую он собирается выехать, свободна на достаточном для обгона расстоянии; транспортное средство впереди не подало сигнал поворота налево и не начало обгон; следующее сзади не начало обгон; по завершении обгона он сможет вернуться на ранее занимаемую полосу, не создавая помех.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('overtaking-1', 'kk', 'Басып озуды бастамас бұрын жүргізуші шығатын жолағы басып озу үшін жеткілікті қашықтықта бос екеніне; алдағы көлік құралы солға бұрылу сигналын бермегеніне және басып озуды бастамағанына; арттағы көлік басып озуды бастамағанына; басып озуды аяқтаған соң кедергі жасамай бұрынғы жолағына орала алатынына көз жеткізуге міндетті.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('overtaking-2', 'overtaking', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('overtaking-2', 'ru', 'Водителю обгоняемого транспортного средства запрещается препятствовать обгону повышением скорости или иными действиями.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('overtaking-2', 'kk', 'Басып озылатын көлік құралының жүргізушісіне жылдамдықты арттыру немесе өзге әрекеттер арқылы басып озуға кедергі келтіруге тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('overtaking-3', 'overtaking', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('overtaking-3', 'ru', 'Обгон запрещён: на регулируемых перекрёстках с выездом на полосу встречного движения, а на нерегулируемых — при движении по второстепенной дороге; на пешеходных переходах; на железнодорожных переездах и перед ними; на мостах, путепроводах, эстакадах и под ними, а также в тоннелях; в конце подъёма, на опасных поворотах и на других участках с ограниченной видимостью.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('overtaking-3', 'kk', 'Басып озуға тыйым салынады: реттелетін қиылыстарда қарсы қозғалыс жолағына шығумен, ал реттелмейтін қиылыстарда қосалқы жолмен жүргенде; жаяу жүргіншілер өткелдерінде; темір жол өткелдерінде және олардың алдында; көпірлерде, жол өтпелерінде, эстакадаларда және олардың астында, сондай-ақ туннельдерде; өрдің соңында, қауіпті бұрылыстарда және көріну шектеулі басқа да учаскелерде.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('stopping', 'stopping', 'pdd-534', 9);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('stopping', 'ru', 'Остановка и стоянка', 'ПДД РК, раздел 12 «Остановка и стоянка»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('stopping', 'kk', 'Тоқтау және тұрақ', 'ЖҚЕ, 12-бөлім «Тоқтау және тұрақ»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('stopping-1', 'stopping', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-1', 'ru', 'Остановка и стоянка разрешаются на правой стороне дороги на обочине, а при её отсутствии — на проезжей части у её края, если это не запрещено Правилами и знаками.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-1', 'kk', 'Тоқтауға және тұраққа, егер Ережелермен және белгілермен тыйым салынбаса, жолдың оң жағында жол жиегінде, ол болмаған кезде — жүру бөлігінің шетінде рұқсат етіледі.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('stopping-2', 'stopping', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-2', 'ru', 'Остановка запрещается: на трамвайных путях; на железнодорожных переездах, в тоннелях, на мостах, путепроводах, эстакадах и под ними; в местах, где расстояние между сплошной линией разметки (кроме обозначающей край проезжей части) или противоположным краем проезжей части и остановившимся транспортным средством менее 3 м.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-2', 'kk', 'Тоқтауға тыйым салынады: трамвай жолдарында; темір жол өткелдерінде, туннельдерде, көпірлерде, жол өтпелерінде, эстакадаларда және олардың астында; тұтас таңба сызығы (жүру бөлігінің шетін белгілейтінінен басқа) немесе жүру бөлігінің қарама-қарсы шеті мен тоқтаған көлік құралы арасындағы қашықтық 3 м-ден аз жерлерде.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('stopping-3', 'stopping', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-3', 'ru', 'Остановка запрещается на пешеходных переходах и ближе 5 м перед ними, а также на остановочных площадках маршрутных транспортных средств и ближе 15 м от них, а при их отсутствии — ближе 15 м от указателя остановки маршрутных транспортных средств или такси.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-3', 'kk', 'Жаяу жүргіншілер өткелдерінде және олардың алдында 5 м-ден жақын жерде, сондай-ақ бағыттағы көлік құралдарының аялдама алаңдарында және олардан 15 м-ден жақын жерде, ал олар болмаған кезде — бағыттағы көлік құралдары немесе такси аялдамасының көрсеткішінен 15 м-ден жақын жерде тоқтауға тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('stopping-4', 'stopping', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-4', 'ru', 'Водитель не должен покидать своё место или оставлять транспортное средство, не приняв мер, исключающих его самопроизвольное движение или использование в отсутствие водителя.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('stopping-4', 'kk', 'Жүргізуші көлік құралының өздігінен қозғалуын немесе жүргізуші жоқта пайдаланылуын болдырмайтын шаралар қолданбай, өз орнын тастап кетпеуі немесе көлік құралын қалдырмауы тиіс.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('pedestrians', 'pedestrians', 'pdd-534', 10);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('pedestrians', 'ru', 'Пешеходы и пешеходные переходы', 'ПДД РК, разделы 4 «Обязанности пешеходов» и 14 «Пешеходные переходы и остановки маршрутных транспортных средств»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('pedestrians', 'kk', 'Жаяу жүргіншілер және жаяу жүргіншілер өткелдері', 'ЖҚЕ, 4-бөлім «Жаяу жүргіншілердің міндеттері» және 14-бөлім «Жаяу жүргіншілер өткелдері және бағыттағы көлік құралдарының аялдамалары»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('pedestrians-1', 'pedestrians', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-1', 'ru', 'Пешеходы должны двигаться по тротуарам или пешеходным дорожкам, а при их отсутствии — по обочинам. Вне населённых пунктов при движении по обочине или краю проезжей части пешеходы должны идти навстречу движению транспортных средств.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-1', 'kk', 'Жаяу жүргіншілер тротуарлармен немесе жаяу жүргіншілер жолдарымен, ал олар болмаған кезде — жол жиектерімен жүруі тиіс. Елді мекендерден тыс жерлерде жол жиегімен немесе жүру бөлігінің шетімен жүргенде жаяу жүргіншілер көлік құралдарының қозғалысына қарсы жүруі тиіс.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('pedestrians-2', 'pedestrians', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-2', 'ru', 'На нерегулируемом пешеходном переходе водитель обязан уступить дорогу пешеходам, переходящим проезжую часть или вступившим на неё для осуществления перехода.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-2', 'kk', 'Реттелмейтін жаяу жүргіншілер өткелінде жүргізуші жүру бөлігін кесіп өтіп жатқан немесе өту үшін оған шыққан жаяу жүргіншілерге жол беруге міндетті.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('pedestrians-3', 'pedestrians', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-3', 'ru', 'Если перед нерегулируемым пешеходным переходом остановилось или снизило скорость транспортное средство, водители других транспортных средств, движущихся в том же направлении, могут продолжить движение, лишь убедившись, что перед ним нет пешеходов.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-3', 'kk', 'Егер реттелмейтін жаяу жүргіншілер өткелінің алдында көлік құралы тоқтаса немесе жылдамдығын азайтса, сол бағытта келе жатқан басқа көлік құралдарының жүргізушілері оның алдында жаяу жүргіншілер жоқ екеніне көз жеткізгеннен кейін ғана жүруді жалғастыра алады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('pedestrians-4', 'pedestrians', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-4', 'ru', 'Водитель обязан уступить дорогу незрячим пешеходам, подающим сигнал белой тростью, во всех случаях.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('pedestrians-4', 'kk', 'Жүргізуші ақ таяқпен белгі беретін көзі көрмейтін жаяу жүргіншілерге барлық жағдайда жол беруге міндетті.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('passengers', 'passengers', 'pdd-534', 11);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('passengers', 'ru', 'Перевозка пассажиров', 'ПДД РК, разделы 5 «Обязанности пассажиров» и 22 «Перевозка пассажиров»');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('passengers', 'kk', 'Жолаушыларды тасымалдау', 'ЖҚЕ, 5-бөлім «Жолаушылардың міндеттері» және 22-бөлім «Жолаушыларды тасымалдау»');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('passengers-1', 'passengers', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('passengers-1', 'ru', 'Посадку и высадку пассажиров производят со стороны тротуара или обочины и только после полной остановки транспортного средства. Пассажирам запрещается открывать двери во время движения.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('passengers-1', 'kk', 'Жолаушыларды отырғызу мен түсіру тротуар немесе жол жиегі жағынан және көлік құралы толық тоқтағаннан кейін ғана жүргізіледі. Жолаушыларға жүріп бара жатқанда есіктерді ашуға тыйым салынады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('passengers-2', 'passengers', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('passengers-2', 'ru', 'Перевозка детей до 12 лет в автомобиле, оборудованном ремнями безопасности, допускается с использованием детских удерживающих устройств или иных средств, позволяющих пристегнуть ребёнка штатными ремнями. На переднем сиденье дети до 12 лет перевозятся только в детском удерживающем устройстве.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('passengers-2', 'kk', 'Қауіпсіздік белдіктерімен жабдықталған автомобильде 12 жасқа дейінгі балаларды тасымалдауға балаларды ұстап тұратын құрылғыларды немесе баланы штаттық белдіктермен байлауға мүмкіндік беретін өзге құралдарды пайдалана отырып рұқсат етіледі. Алдыңғы орындықта 12 жасқа дейінгі балалар тек балаларды ұстап тұратын құрылғыда тасымалданады.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('passengers-3', 'passengers', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('passengers-3', 'ru', 'Пассажиры при поездке на транспортном средстве, оборудованном ремнями безопасности, обязаны быть пристёгнутыми, а при поездке на мотоцикле — быть в застёгнутом мотошлеме.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('passengers-3', 'kk', 'Жолаушылар қауіпсіздік белдіктерімен жабдықталған көлік құралымен жүргенде белдікпен байланған, ал мотоциклмен жүргенде түймеленген мотошлемде болуға міндетті.');
INSERT INTO rule_sections (id, topic_id, source_id, sort_order) VALUES ('safety', 'safety', 'pdd-534', 12);
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('safety', 'ru', 'Первая помощь и безопасность', 'ПДД РК, раздел 7 «Применение аварийной сигнализации и знака аварийной остановки»; общие рекомендации по первой помощи');
INSERT INTO rule_section_translations (section_id, lang, title, reference) VALUES ('safety', 'kk', 'Алғашқы көмек және қауіпсіздік', 'ЖҚЕ, 7-бөлім «Авариялық дабыл мен авариялық тоқтау белгісін қолдану»; алғашқы көмек бойынша жалпы ұсынымдар');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('safety-1', 'safety', 1, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-1', 'ru', 'Аварийная сигнализация включается: при дорожно-транспортном происшествии; при вынужденной остановке в местах, где остановка запрещена; при ослеплении водителя светом фар; при буксировке (на буксируемом транспортном средстве), а также в других случаях для предупреждения участников движения об опасности.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-1', 'kk', 'Авариялық дабыл қосылады: жол-көлік оқиғасы кезінде; тоқтауға тыйым салынған жерлерде мәжбүрлі тоқтаған кезде; жүргізушінің көзін фара жарығы шағылыстырғанда; сүйретіп апару кезінде (сүйретілетін көлік құралында), сондай-ақ қозғалысқа қатысушыларды қауіп туралы ескерту үшін өзге де жағдайларда.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('safety-2', 'safety', 2, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-2', 'ru', 'Знак аварийной остановки выставляется на расстоянии, обеспечивающем своевременное предупреждение других водителей: не менее 15 м от транспортного средства в населённых пунктах и не менее 30 м — вне населённых пунктов.');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-2', 'kk', 'Авариялық тоқтау белгісі басқа жүргізушілерді уақтылы ескертуді қамтамасыз ететін қашықтықта қойылады: елді мекендерде көлік құралынан кемінде 15 м және елді мекендерден тыс жерлерде кемінде 30 м.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('safety-3', 'safety', 3, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-3', 'ru', 'При ДТП с пострадавшими вызовите помощь по единому номеру 112 (скорая помощь — 103, полиция — 102). Не перемещайте пострадавшего без крайней необходимости (угроза пожара, взрыва, наезда).');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-3', 'kk', 'Зардап шеккендері бар ЖКО кезінде 112 бірыңғай нөмірі бойынша көмек шақырыңыз (жедел жәрдем — 103, полиция — 102). Аса қажеттілік болмаса (өрт, жарылыс, қағып кету қаупі), зардап шеккенді орнынан жылжытпаңыз.');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('safety-4', 'safety', 4, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-4', 'ru', 'Если пострадавший без сознания и не дышит нормально, начинайте сердечно-лёгочную реанимацию: 30 надавливаний на центр грудной клетки (глубина около 5–6 см, частота 100–120 в минуту), затем 2 вдоха, если вы обучены и готовы их делать. Продолжайте до прибытия медиков. (Общие рекомендации по первой помощи, не текст ПДД.)');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-4', 'kk', 'Егер зардап шеккен ессіз болса және қалыпты тыныс алмаса, жүрек-өкпе реанимациясын бастаңыз: кеуде қуысының ортасына 30 рет басу (тереңдігі шамамен 5–6 см, жиілігі минутына 100–120), содан кейін үйретілген болсаңыз және дайын болсаңыз, 2 рет үрлеу. Дәрігерлер келгенге дейін жалғастырыңыз. (Алғашқы көмек бойынша жалпы ұсынымдар, ЖҚЕ мәтіні емес.)');
INSERT INTO rule_items (id, section_id, sort_order, clause_number, is_verified) VALUES ('safety-5', 'safety', 5, NULL, FALSE);
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-5', 'ru', 'При сильном наружном кровотечении прижмите рану и наложите давящую повязку; кровоостанавливающий жгут применяется при угрожающем жизни кровотечении из конечности, с обязательной запиской о времени наложения. (Общие рекомендации по первой помощи.)');
INSERT INTO rule_item_translations (item_id, lang, body) VALUES ('safety-5', 'kk', 'Қатты сыртқы қан кеткенде жараны басып, қысатын таңғыш салыңыз; қан тоқтататын бұрау аяқ-қолдан өмірге қауіп төндіретін қан кеткенде, салынған уақыты туралы міндетті жазбамен қолданылады. (Алғашқы көмек бойынша жалпы ұсынымдар.)');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q001', 'general', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q001', 'ru', 'Какое движение транспортных средств установлено на дорогах Республики Казахстан?', 'В Казахстане установлено правостороннее движение: транспортные средства движутся по правой стороне проезжей части.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q001', 'kk', 'Қазақстан Республикасының жолдарында көлік құралдарының қандай қозғалысы белгіленген?', 'Қазақстанда оң жақты қозғалыс белгіленген: көлік құралдары жүру бөлігінің оң жағымен жүреді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q001-a', 'q001', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q001-a', 'ru', 'Левостороннее.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q001-a', 'kk', 'Сол жақты.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q001-b', 'q001', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q001-b', 'ru', 'Правостороннее.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q001-b', 'kk', 'Оң жақты.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q001-c', 'q001', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q001-c', 'ru', 'Определяется только дорожной разметкой.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q001-c', 'kk', 'Тек жол таңбасымен анықталады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q001', 'general-2', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q002', 'general', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q002', 'ru', 'Что означает требование «Уступить дорогу»?', '«Уступить дорогу» не всегда означает остановку. Главное — своими действиями не вынуждать тех, у кого есть преимущество, тормозить или менять направление.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q002', 'kk', '«Жол беру» талабы нені білдіреді?', '«Жол беру» әрқашан тоқтауды білдірмейді. Бастысы — өз әрекеттеріңізбен басымдығы барларды тежеуге немесе бағытын өзгертуге мәжбүрлемеу.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q002-a', 'q002', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q002-a', 'ru', 'Всегда полностью остановиться перед перекрёстком.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q002-a', 'kk', 'Қиылыс алдында әрқашан толық тоқтау.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q002-b', 'q002', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q002-b', 'ru', 'Не начинать, не возобновлять и не продолжать движение, не совершать манёвр, если это вынудит участников, имеющих преимущество, изменить направление или скорость.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q002-b', 'kk', 'Егер бұл басымдығы бар қатысушыларды бағытын немесе жылдамдығын өзгертуге мәжбүр етсе, қозғалысты бастамау, қайта бастамау және жалғастырмау, маневр жасамау.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q002-c', 'q002', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q002-c', 'ru', 'Снизить скорость до 20 км/ч и продолжить движение.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q002-c', 'kk', 'Жылдамдықты сағатына 20 км-ге дейін төмендетіп, жүруді жалғастыру.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q002', 'general-4', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q003', 'general', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q003', 'ru', 'Перед перекрёстком установлен знак «Главная дорога», а светофор показывает красный сигнал. Как поступить?', 'Работающий светофор (кроме режима мигающего жёлтого) важнее знаков приоритета. Знаки приоритета действуют, когда светофор выключен или мигает жёлтым.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q003', 'kk', 'Қиылыс алдында «Басты жол» белгісі орнатылған, ал бағдаршам қызыл сигнал көрсетіп тұр. Қалай әрекет ету керек?', 'Жұмыс істеп тұрған бағдаршам (жыпылықтайтын сары режимінен басқа) басымдық белгілерінен маңыздырақ. Басымдық белгілері бағдаршам сөніп тұрғанда немесе сары жыпылықтағанда әрекет етеді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q003-a', 'q003', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q003-a', 'ru', 'Проехать: знак приоритета важнее светофора.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q003-a', 'kk', 'Өту: басымдық белгісі бағдаршамнан маңызды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q003-b', 'q003', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q003-b', 'ru', 'Остановиться: сигналы светофора имеют приоритет над знаками приоритета.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q003-b', 'kk', 'Тоқтау: бағдаршам сигналдары басымдық белгілерінен басым.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q003-c', 'q003', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q003-c', 'ru', 'Проехать, если нет пешеходов.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q003-c', 'kk', 'Жаяу жүргіншілер болмаса, өту.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q003', 'general-5', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q004', 'driver', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q004', 'ru', 'Можно ли передать управление автомобилем человеку, у которого нет при себе водительского удостоверения?', 'Передавать управление лицу без водительского удостоверения соответствующей категории запрещено. Исключение — учебная езда с инструктором по установленным правилам.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q004', 'kk', 'Жанында жүргізуші куәлігі жоқ адамға автомобильді басқаруды беруге бола ма?', 'Тиісті санаттағы жүргізуші куәлігі жоқ адамға басқаруды беруге тыйым салынады. Ерекшелік — белгіленген ережелер бойынша нұсқаушымен оқу жүргізуі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q004-a', 'q004', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q004-a', 'ru', 'Можно, если рядом сидит опытный водитель.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q004-a', 'kk', 'Жанында тәжірибелі жүргізуші отырса, болады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q004-b', 'q004', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q004-b', 'ru', 'Нельзя, кроме обучения вождению в установленном порядке.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q004-b', 'kk', 'Белгіленген тәртіппен жүргізуді үйретуден басқа жағдайда болмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q004-c', 'q004', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q004-c', 'ru', 'Можно только вне населённых пунктов.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q004-c', 'kk', 'Тек елді мекендерден тыс жерлерде болады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q004', 'driver-5', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q005', 'driver', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q005', 'ru', 'Разрешается ли водителю во время движения разговаривать по телефону, держа его в руке?', 'Телефон в руке отвлекает внимание и занимает руку. Во время движения можно говорить только с помощью гарнитуры или громкой связи.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q005', 'kk', 'Жүргізушіге жүріп бара жатқанда телефонды қолымен ұстап сөйлесуге рұқсат етіле ме?', 'Қолдағы телефон зейінді бөледі және қолды бос емес етеді. Жүріп бара жатқанда тек гарнитура немесе дауыс зорайтқыш байланыс арқылы сөйлесуге болады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q005-a', 'q005', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q005-a', 'ru', 'Разрешается при скорости до 20 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q005-a', 'kk', 'Сағатына 20 км-ге дейінгі жылдамдықта рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q005-b', 'q005', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q005-b', 'ru', 'Разрешается в пробке.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q005-b', 'kk', 'Кептелісте рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q005-c', 'q005', 'c', 3, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q005-c', 'ru', 'Запрещается; допускается только разговор через устройство громкой связи (hands-free).');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q005-c', 'kk', 'Тыйым салынады; тек қолды пайдаланбай сөйлесу құрылғысы (hands-free) арқылы сөйлесуге болады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q005', 'driver-4', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q006', 'driver', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q006', 'ru', 'Кто обязан быть пристёгнут ремнём безопасности в автомобиле, оборудованном ремнями?', 'Водитель обязан быть пристёгнут сам и не перевозить непристёгнутых пассажиров — это касается и заднего ряда.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q006', 'kk', 'Қауіпсіздік белдіктерімен жабдықталған автомобильде кім белдікпен байлануға міндетті?', 'Жүргізуші өзі белдікпен байлануға және байланбаған жолаушыларды тасымалдамауға міндетті — бұл артқы қатарға да қатысты.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q006-a', 'q006', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q006-a', 'ru', 'Только водитель.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q006-a', 'kk', 'Тек жүргізуші.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q006-b', 'q006', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q006-b', 'ru', 'Водитель и пассажир на переднем сиденье.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q006-b', 'kk', 'Жүргізуші және алдыңғы орындықтағы жолаушы.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q006-c', 'q006', 'c', 3, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q006-c', 'ru', 'Водитель и все пассажиры.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q006-c', 'kk', 'Жүргізуші және барлық жолаушылар.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q006', 'driver-2', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q006', 'passengers-3', 1);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q007', 'triangle', '{"type":"triangle","area":"outside","distance":30}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q007', 'driver', 'ill-q007', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q007', 'ru', 'Автомобиль вынужденно остановился на дороге вне населённого пункта. На каком расстоянии нужно выставить знак аварийной остановки?', 'Вне населённых пунктов скорости выше, поэтому знак ставят дальше — не менее 30 м. В населённом пункте — не менее 15 м.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q007', 'kk', 'Автомобиль елді мекеннен тыс жолда мәжбүрлі тоқтады. Авариялық тоқтау белгісін қандай қашықтықта қою керек?', 'Елді мекендерден тыс жерлерде жылдамдық жоғары, сондықтан белгі алысырақ — кемінде 30 м қойылады. Елді мекенде — кемінде 15 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q007-a', 'q007', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q007-a', 'ru', 'Не менее 15 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q007-a', 'kk', 'Кемінде 15 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q007-b', 'q007', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q007-b', 'ru', 'Не менее 30 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q007-b', 'kk', 'Кемінде 30 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q007-c', 'q007', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q007-c', 'ru', 'Не менее 100 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q007-c', 'kk', 'Кемінде 100 м.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q007', 'safety-2', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q008', 'sign', '{"type":"sign","sign":"give-way"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q008', 'signs', 'ill-q008', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q008', 'ru', 'Что означает этот знак?', 'Перевёрнутый треугольник с красной каймой — знак «Уступите дорогу». Водитель должен уступить транспорту на пересекаемой дороге, а при наличии таблички — на главной дороге.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q008', 'kk', 'Бұл белгі нені білдіреді?', 'Қызыл жиекті төңкерілген үшбұрыш — «Жол беріңіз» белгісі. Жүргізуші қиылысатын жолдағы, ал тақтайша болса — басты жолдағы көлікке жол беруі тиіс.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q008-a', 'q008', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q008-a', 'ru', '«Главная дорога».');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q008-a', 'kk', '«Басты жол».');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q008-b', 'q008', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q008-b', 'ru', '«Уступите дорогу».');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q008-b', 'kk', '«Жол беріңіз».');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q008-c', 'q008', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q008-c', 'ru', '«Движение без остановки запрещено».');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q008-c', 'kk', '«Тоқтамай жүруге тыйым салынады».');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q008', 'signs-3', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q009', 'sign', '{"type":"sign","sign":"stop"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q009', 'signs', 'ill-q009', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q009', 'ru', 'Что требует от водителя этот знак?', 'Знак STOP требует обязательной остановки всегда, даже если дорога кажется свободной, после чего нужно уступить дорогу транспорту на пересекаемой дороге.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q009', 'kk', 'Бұл белгі жүргізушіден нені талап етеді?', 'STOP белгісі жол бос болып көрінсе де, әрқашан міндетті түрде тоқтауды талап етеді, содан кейін қиылысатын жолдағы көлікке жол беру керек.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q009-a', 'q009', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q009-a', 'ru', 'Остановиться, только если по пересекаемой дороге приближаются другие автомобили.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q009-a', 'kk', 'Қиылысатын жолмен басқа автомобильдер жақындаса ғана тоқтау.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q009-b', 'q009', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q009-b', 'ru', 'Остановиться у стоп-линии (а при её отсутствии — у края пересекаемой проезжей части) и уступить дорогу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q009-b', 'kk', 'Тоқтау сызығының алдында (ол болмаса — қиылысатын жүру бөлігінің шетінде) тоқтап, жол беру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q009-c', 'q009', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q009-c', 'ru', 'Запрещает стоянку перед перекрёстком.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q009-c', 'kk', 'Қиылыс алдында тұраққа тыйым салады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q009', 'signs-3', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q009', 'markings-3', 1);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q010', 'sign', '{"type":"sign","sign":"priority-road"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q010', 'signs', 'ill-q010', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q010', 'ru', 'Как называется этот знак?', 'Жёлтый ромб в белой рамке — знак «Главная дорога». Он предоставляет право преимущественного проезда нерегулируемых перекрёстков.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q010', 'kk', 'Бұл белгі қалай аталады?', 'Ақ жиектегі сары ромб — «Басты жол» белгісі. Ол реттелмейтін қиылыстардан басым өту құқығын береді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q010-a', 'q010', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q010-a', 'ru', '«Главная дорога».');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q010-a', 'kk', '«Басты жол».');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q010-b', 'q010', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q010-b', 'ru', '«Конец главной дороги».');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q010-b', 'kk', '«Басты жолдың соңы».');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q010-c', 'q010', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q010-c', 'ru', '«Преимущество перед встречным движением».');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q010-c', 'kk', '«Қарсы қозғалыстан басымдық».');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q010', 'signs-3', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q011', 'sign', '{"type":"sign","sign":"no-overtaking"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q011', 'signs', 'ill-q011', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q011', 'ru', 'Что запрещает этот знак?', 'Знак «Обгон запрещён» запрещает обгонять, но не запрещает перестраиваться без выезда для обгона. Тихоходные транспортные средства, повозки, велосипеды, мопеды и мотоциклы без коляски обгонять можно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q011', 'kk', 'Бұл белгі неге тыйым салады?', '«Басып озуға тыйым салынады» белгісі басып озуға тыйым салады, бірақ басып озусыз қайта құрылуға тыйым салмайды. Баяу жүретін көліктерді, арбаларды, велосипедтерді, мопедтерді және бүйірлі арбасыз мотоциклдерді басып озуға болады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q011-a', 'q011', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q011-a', 'ru', 'Любое перестроение в соседнюю полосу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q011-a', 'kk', 'Көрші жолаққа кез келген қайта құрылуға.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q011-b', 'q011', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q011-b', 'ru', 'Обгон всех транспортных средств, кроме тихоходных, гужевых повозок, велосипедов, мопедов и двухколёсных мотоциклов без коляски.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q011-b', 'kk', 'Баяу жүретін көлік құралдарынан, ат арбаларынан, велосипедтерден, мопедтерден және бүйірлі арбасыз екі дөңгелекті мотоциклдерден басқа барлық көлік құралдарын басып озуға.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q011-c', 'q011', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q011-c', 'ru', 'Движение легковых автомобилей.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q011-c', 'kk', 'Жеңіл автомобильдердің жүруіне.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q011', 'signs-4', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q012', 'sign', '{"type":"sign","sign":"no-stopping"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q012', 'signs', 'ill-q012', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q012', 'ru', 'Что запрещает этот знак?', 'Знак с двумя перекрещёнными красными полосами на синем фоне — «Остановка запрещена»: он запрещает и остановку, и стоянку. Знак с одной наклонной полосой — «Стоянка запрещена» — запрещает только стоянку.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q012', 'kk', 'Бұл белгі неге тыйым салады?', 'Көк фондағы екі айқасқан қызыл жолағы бар белгі — «Тоқтауға тыйым салынады»: ол тоқтауға да, тұраққа да тыйым салады. Бір көлбеу жолағы бар белгі — «Тұраққа тыйым салынады» — тек тұраққа тыйым салады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q012-a', 'q012', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q012-a', 'ru', 'Только стоянку.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q012-a', 'kk', 'Тек тұраққа.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q012-b', 'q012', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q012-b', 'ru', 'И остановку, и стоянку.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q012-b', 'kk', 'Тоқтауға да, тұраққа да.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q012-c', 'q012', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q012-c', 'ru', 'Въезд всех транспортных средств.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q012-c', 'kk', 'Барлық көлік құралдарының кіруіне.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q012', 'signs-4', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q013', 'sign', '{"type":"sign","sign":"children"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q013', 'signs', 'ill-q013', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q013', 'ru', 'Как должен действовать водитель, увидев этот знак?', 'Это предупреждающий знак «Дети». Он не требует остановки, но предупреждает об опасном участке у детских учреждений и площадок.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q013', 'kk', 'Бұл белгіні көргенде жүргізуші қалай әрекет етуі тиіс?', 'Бұл «Балалар» ескерту белгісі. Ол тоқтауды талап етпейді, бірақ балалар мекемелері мен алаңдары маңындағы қауіпті учаске туралы ескертеді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q013-a', 'q013', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q013-a', 'ru', 'Быть особенно внимательным: возможно появление детей на проезжей части; при необходимости снизить скорость.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q013-a', 'kk', 'Аса мұқият болу: жүру бөлігінде балалар пайда болуы мүмкін; қажет болса жылдамдықты азайту.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q013-b', 'q013', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q013-b', 'ru', 'Обязательно остановиться.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q013-b', 'kk', 'Міндетті түрде тоқтау.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q013-c', 'q013', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q013-c', 'ru', 'Подать звуковой сигнал.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q013-c', 'kk', 'Дыбыстық сигнал беру.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q013', 'signs-2', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q014', 'road', '{"type":"road","marking":"solid","scene":"plain"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q014', 'markings', 'ill-q014', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q014', 'ru', 'Разрешается ли пересекать сплошную линию разметки, разделяющую встречные потоки?', 'Сплошная линия 1.1 обозначает границу, которую пересекать нельзя. Обгон тихоходного транспорта не даёт права её пересечь.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q014', 'kk', 'Қарсы ағындарды бөлетін тұтас таңба сызығын қиып өтуге рұқсат етіле ме?', '1.1 тұтас сызығы қиып өтуге болмайтын шекараны білдіреді. Баяу жүретін көлікті басып озу оны қиып өтуге құқық бермейді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q014-a', 'q014', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q014-a', 'ru', 'Разрешается при обгоне тихоходного транспорта.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q014-a', 'kk', 'Баяу жүретін көлікті басып озғанда рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q014-b', 'q014', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q014-b', 'ru', 'Запрещается.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q014-b', 'kk', 'Тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q014-c', 'q014', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q014-c', 'ru', 'Разрешается в тёмное время суток.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q014-c', 'kk', 'Тәуліктің қараңғы уақытында рұқсат етіледі.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q014', 'markings-1', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q015', 'road', '{"type":"road","marking":"broken","scene":"overtake"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q015', 'markings', 'ill-q015', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q015', 'ru', 'Разметка прерывистая, встречная полоса свободна на большом расстоянии, видимость хорошая. Разрешён ли обгон синему автомобилю?', 'Прерывистую линию можно пересекать. Перед обгоном нужно убедиться, что встречная полоса свободна, впереди идущий не подал сигнал поворота налево, а сзади никто не начал обгон.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q015', 'kk', 'Таңба үзік, қарсы жолақ алысқа дейін бос, көріну жақсы. Көк автомобильге басып озуға рұқсат етіле ме?', 'Үзік сызықты қиып өтуге болады. Басып озар алдында қарсы жолақтың бос екеніне, алдағы көліктің солға бұрылу сигналын бермегеніне, арттағы ешкім басып озуды бастамағанына көз жеткізу керек.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q015-a', 'q015', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q015-a', 'ru', 'Разрешён, если водитель убедится в безопасности манёвра.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q015-a', 'kk', 'Жүргізуші маневрдің қауіпсіз екеніне көз жеткізсе, рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q015-b', 'q015', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q015-b', 'ru', 'Запрещён в любом случае.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q015-b', 'kk', 'Кез келген жағдайда тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q015-c', 'q015', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q015-c', 'ru', 'Разрешён только с включённым дальним светом.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q015-c', 'kk', 'Тек алыс жарық қосулы болғанда рұқсат етіледі.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q015', 'markings-2', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q015', 'overtaking-1', 1);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q016', 'markings', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q016', 'ru', 'Временные дорожные знаки противоречат нанесённой на дорогу разметке. Чем руководствоваться?', 'При противоречии временных знаков и разметки приоритет имеют знаки. Обычно так бывает при дорожных работах, когда схема движения временно изменена.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q016', 'kk', 'Уақытша жол белгілері жолға түсірілген таңбаға қайшы келеді. Нені басшылыққа алу керек?', 'Уақытша белгілер мен таңба қайшы келгенде белгілер басым болады. Әдетте бұл қозғалыс сызбасы уақытша өзгертілген жол жұмыстары кезінде болады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q016-a', 'q016', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q016-a', 'ru', 'Разметкой.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q016-a', 'kk', 'Таңбаны.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q016-b', 'q016', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q016-b', 'ru', 'Знаками.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q016-b', 'kk', 'Белгілерді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q016-c', 'q016', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q016-c', 'ru', 'Тем, что удобнее водителю.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q016-c', 'kk', 'Жүргізушіге ыңғайлысын.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q016', 'markings-4', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q016', 'signs-6', 1);
