INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q017', 'signals', 'ill-q017', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q017', 'ru', 'Что означает мигающий жёлтый сигнал светофора?', 'При мигающем жёлтом перекрёсток считается нерегулируемым: очерёдность определяется знаками приоритета, а при их отсутствии — правилом «помехи справа».');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q017', 'kk', 'Бағдаршамның жыпылықтайтын сары сигналы нені білдіреді?', 'Жыпылықтайтын сары кезінде қиылыс реттелмейтін болып саналады: кезектілік басымдық белгілерімен, ал олар болмаса — «оң жақтан кедергі» ережесімен анықталады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q017-a', 'q017', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q017-a', 'ru', 'Движение запрещено.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q017-a', 'kk', 'Қозғалысқа тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q017-b', 'q017', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q017-b', 'ru', 'Разрешает движение и информирует о нерегулируемом перекрёстке или пешеходном переходе, предупреждает об опасности.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q017-b', 'kk', 'Қозғалысқа рұқсат береді және реттелмейтін қиылыс немесе жаяу жүргіншілер өткелі туралы хабарлайды, қауіп туралы ескертеді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q017-c', 'q017', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q017-c', 'ru', 'Скоро включится зелёный сигнал.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q017-c', 'kk', 'Жақында жасыл сигнал қосылады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q017', 'signals-3', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q018', 'light', '{"type":"light","state":"yellow"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q018', 'signals', 'ill-q018', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q018', 'ru', 'Загорелся жёлтый сигнал. Водитель может остановиться только с помощью экстренного торможения. Как ему поступить?', 'Жёлтый сигнал запрещает движение, но если остановиться можно только экстренным торможением, Правила разрешают продолжить движение — резкая остановка может привести к наезду сзади.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q018', 'kk', 'Сары сигнал жанды. Жүргізуші тек шұғыл тежеу арқылы ғана тоқтай алады. Ол қалай әрекет етуі керек?', 'Сары сигнал қозғалысқа тыйым салады, бірақ тек шұғыл тежеумен ғана тоқтауға болатын болса, Ережелер жүруді жалғастыруға рұқсат береді — кенет тоқтау арттан соғылуға әкелуі мүмкін.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q018-a', 'q018', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q018-a', 'ru', 'Экстренно затормозить в любом случае.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q018-a', 'kk', 'Кез келген жағдайда шұғыл тежеу.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q018-b', 'q018', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q018-b', 'ru', 'Продолжить движение — это разрешено.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q018-b', 'kk', 'Жүруді жалғастыру — бұған рұқсат етілген.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q018-c', 'q018', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q018-c', 'ru', 'Остановиться прямо на перекрёстке.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q018-c', 'kk', 'Тура қиылыстың өзінде тоқтау.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q018', 'signals-2', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q019', 'light', '{"type":"light","state":"red-yellow"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q019', 'signals', 'ill-q019', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q019', 'ru', 'Что означает одновременное включение красного и жёлтого сигналов?', 'Красный с жёлтым — всё ещё запрещающий сигнал. Начинать движение можно только после включения зелёного.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q019', 'kk', 'Қызыл және сары сигналдардың бір мезгілде қосылуы нені білдіреді?', 'Қызыл мен сары — әлі де тыйым салатын сигнал. Қозғалысты тек жасыл қосылғаннан кейін ғана бастауға болады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q019-a', 'q019', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q019-a', 'ru', 'Разрешено начинать движение.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q019-a', 'kk', 'Қозғалысты бастауға рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q019-b', 'q019', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q019-b', 'ru', 'Движение запрещено; скоро будет включён зелёный сигнал.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q019-b', 'kk', 'Қозғалысқа тыйым салынады; жақында жасыл сигнал қосылады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q019-c', 'q019', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q019-c', 'ru', 'Светофор неисправен.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q019-c', 'kk', 'Бағдаршам ақаулы.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q019', 'signals-4', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q020', 'signals', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q020', 'ru', 'Регулировщик подаёт сигнал, который противоречит сигналу светофора. Чем руководствоваться?', 'Сигналы регулировщика имеют наивысший приоритет — над светофором, знаками и разметкой.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q020', 'kk', 'Реттеуші бағдаршам сигналына қайшы келетін сигнал береді. Нені басшылыққа алу керек?', 'Реттеушінің сигналдары ең жоғары басымдыққа ие — бағдаршамнан, белгілер мен таңбадан жоғары.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q020-a', 'q020', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q020-a', 'ru', 'Сигналом светофора.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q020-a', 'kk', 'Бағдаршам сигналын.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q020-b', 'q020', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q020-b', 'ru', 'Сигналом регулировщика.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q020-b', 'kk', 'Реттеушінің сигналын.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q020-c', 'q020', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q020-c', 'ru', 'Знаками приоритета.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q020-c', 'kk', 'Басымдық белгілерін.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q020', 'signals-6', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q020', 'general-5', 1);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q021', 'light', '{"type":"light","state":"red-arrow-right"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q021', 'signals', 'ill-q021', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q021', 'ru', 'Горит красный сигнал и зелёная стрелка направо в дополнительной секции. Можно ли повернуть направо?', 'Стрелка в дополнительной секции разрешает движение в своём направлении, но не даёт преимущества: нужно уступить транспорту, движущемуся с других направлений (и пешеходам).');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q021', 'kk', 'Қызыл сигнал мен қосымша секцияда оңға қараған жасыл бағдарше жанып тұр. Оңға бұрылуға бола ма?', 'Қосымша секциядағы бағдарше өз бағытында қозғалуға рұқсат береді, бірақ басымдық бермейді: басқа бағыттардан келе жатқан көлікке (және жаяу жүргіншілерге) жол беру керек.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q021-a', 'q021', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q021-a', 'ru', 'Нельзя, пока горит красный.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q021-a', 'kk', 'Қызыл жанып тұрғанда болмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q021-b', 'q021', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q021-b', 'ru', 'Можно, уступив дорогу транспортным средствам, движущимся с других направлений.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q021-b', 'kk', 'Басқа бағыттардан келе жатқан көлік құралдарына жол беріп, болады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q021-c', 'q021', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q021-c', 'ru', 'Можно, преимущество у вас.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q021-c', 'kk', 'Болады, басымдық сізде.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q021', 'signals-5', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q022', 'intersection', '{"type":"intersection","cars":[{"from":"s","turn":"straight","color":"blue","label":"A"},{"from":"e","turn":"straight","color":"red","label":"B"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q022', 'intersections', 'ill-q022', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q022', 'ru', 'Перекрёсток равнозначных дорог без светофора и знаков. Кто проедет первым?', 'На перекрёстке равнозначных дорог действует правило «помехи справа». Для синего A красный B приближается справа, поэтому A уступает.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q022', 'kk', 'Бағдаршамсыз және белгісіз тең маңызды жолдардың қиылысы. Кім бірінші өтеді?', 'Тең маңызды жолдардың қиылысында «оң жақтан кедергі» ережесі әрекет етеді. Көк A үшін қызыл B оң жақтан жақындап келеді, сондықтан A жол береді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q022-a', 'q022', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q022-a', 'ru', 'Синий автомобиль A.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q022-a', 'kk', 'Көк A автомобилі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q022-b', 'q022', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q022-b', 'ru', 'Красный автомобиль B.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q022-b', 'kk', 'Қызыл B автомобилі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q022-c', 'q022', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q022-c', 'ru', 'Оба одновременно.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q022-c', 'kk', 'Екеуі бір мезгілде.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q022', 'intersections-5', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q023', 'intersection', '{"type":"intersection","light":"green","cars":[{"from":"s","turn":"left","color":"blue","label":"A"},{"from":"n","turn":"straight","color":"red","label":"B"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q023', 'intersections', 'ill-q023', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q023', 'ru', 'Синий автомобиль A поворачивает налево на зелёный сигнал. Навстречу прямо едет красный B. Как поступить водителю A?', 'При повороте налево по зелёному сигналу нужно уступить транспорту, движущемуся со встречного направления прямо или направо.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q023', 'kk', 'Көк A автомобилі жасыл сигналда солға бұрылады. Қарсы тура қызыл B келе жатыр. A жүргізушісі қалай әрекет етуі керек?', 'Жасыл сигнал бойынша солға бұрылғанда қарсы бағыттан тура немесе оңға келе жатқан көлікке жол беру керек.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q023-a', 'q023', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q023-a', 'ru', 'Проехать первым: он уже на перекрёстке.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q023-a', 'kk', 'Бірінші өту: ол қиылыста тұр.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q023-b', 'q023', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q023-b', 'ru', 'Уступить дорогу встречному B.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q023-b', 'kk', 'Қарсы келе жатқан B-ға жол беру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q023-c', 'q023', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q023-c', 'ru', 'Подать звуковой сигнал и проехать.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q023-c', 'kk', 'Дыбыстық сигнал беріп, өту.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q023', 'intersections-3', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q024', 'intersection', '{"type":"intersection","main":"ew","signs":[{"at":"s","sign":"give-way"}],"cars":[{"from":"s","turn":"straight","color":"blue","label":"A"},{"from":"w","turn":"straight","color":"red","label":"B"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q024', 'intersections', 'ill-q024', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q024', 'ru', 'Синий A подъезжает к перекрёстку со знаком «Уступите дорогу», красный B движется по главной дороге слева. Кто проедет первым?', 'На перекрёстке неравнозначных дорог правило «помехи справа» не применяется между главной и второстепенной. Водитель на второстепенной уступает всем на главной — независимо от стороны, откуда они едут.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q024', 'kk', 'Көк A «Жол беріңіз» белгісі бар қиылысқа жақындап келеді, қызыл B сол жақтан басты жолмен келе жатыр. Кім бірінші өтеді?', 'Тең емес жолдардың қиылысында басты және қосалқы жол арасында «оң жақтан кедергі» ережесі қолданылмайды. Қосалқы жолдағы жүргізуші басты жолдағылардың барлығына — олар қай жақтан келе жатқанына қарамастан — жол береді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q024-a', 'q024', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q024-a', 'ru', 'Синий A: B приближается слева.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q024-a', 'kk', 'Көк A: B сол жақтан жақындап келеді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q024-b', 'q024', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q024-b', 'ru', 'Красный B: он на главной дороге.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q024-b', 'kk', 'Қызыл B: ол басты жолда.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q024-c', 'q024', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q024-c', 'ru', 'Тот, кто подъехал раньше.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q024-c', 'kk', 'Ертерек жеткені.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q024', 'intersections-4', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q024', 'signs-3', 1);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q025', 'intersection', '{"type":"intersection","light":"green","pedestrian":"e","cars":[{"from":"s","turn":"right","color":"blue","label":"A"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q025', 'intersections', 'ill-q025', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q025', 'ru', 'Синий A поворачивает направо на зелёный сигнал. Пешеход переходит проезжую часть, на которую поворачивает A. Как поступить?', 'При повороте водитель обязан уступить пешеходам, пересекающим проезжую часть, на которую он поворачивает, — даже при зелёном сигнале.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q025', 'kk', 'Көк A жасыл сигналда оңға бұрылады. Жаяу жүргінші A бұрылатын жүру бөлігін кесіп өтіп жатыр. Қалай әрекет ету керек?', 'Бұрылған кезде жүргізуші өзі бұрылатын жүру бөлігін кесіп өтіп жатқан жаяу жүргіншілерге — жасыл сигнал болса да — жол беруге міндетті.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q025-a', 'q025', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q025-a', 'ru', 'Уступить дорогу пешеходу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q025-a', 'kk', 'Жаяу жүргіншіге жол беру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q025-b', 'q025', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q025-b', 'ru', 'Проехать: у водителя зелёный сигнал.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q025-b', 'kk', 'Өту: жүргізушіде жасыл сигнал.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q025-c', 'q025', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q025-c', 'ru', 'Объехать пешехода по встречной полосе.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q025-c', 'kk', 'Жаяу жүргіншіні қарсы жолақпен айналып өту.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q025', 'intersections-1', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q026', 'intersections', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q026', 'ru', 'Горит зелёный сигнал, но сразу за перекрёстком образовался затор. Можно ли выехать на перекрёсток?', 'Зелёный сигнал не даёт права «запереть» перекрёсток. Если за ним затор, дождитесь, пока освободится место.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q026', 'kk', 'Жасыл сигнал жанып тұр, бірақ қиылыстан кейін бірден кептеліс пайда болды. Қиылысқа шығуға бола ма?', 'Жасыл сигнал қиылысты «бітеп тастауға» құқық бермейді. Егер одан кейін кептеліс болса, орын босағанша күтіңіз.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q026-a', 'q026', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q026-a', 'ru', 'Можно: горит зелёный.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q026-a', 'kk', 'Болады: жасыл жанып тұр.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q026-b', 'q026', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q026-b', 'ru', 'Нельзя, если придётся остановиться на перекрёстке и помешать поперечному движению.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q026-b', 'kk', 'Қиылыста тоқтап, көлденең қозғалысқа кедергі келтіруге тура келсе, болмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q026-c', 'q026', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q026-c', 'ru', 'Можно, включив аварийную сигнализацию.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q026-c', 'kk', 'Авариялық дабылды қосып, болады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q026', 'intersections-2', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q027', 'sign', '{"type":"sign","sign":"settlement"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q027', 'speed', 'ill-q027', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q027', 'ru', 'С какой максимальной скоростью можно двигаться в населённом пункте, если знаками не установлено иное?', 'Общее ограничение в населённых пунктах — не более 60 км/ч. Знаками может быть установлено другое значение.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q027', 'kk', 'Егер белгілермен өзгеше белгіленбесе, елді мекенде ең жоғары қандай жылдамдықпен жүруге болады?', 'Елді мекендердегі жалпы шектеу — сағатына 60 км-ден аспайды. Белгілермен басқа мән белгіленуі мүмкін.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q027-a', 'q027', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q027-a', 'ru', '50 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q027-a', 'kk', 'Сағатына 50 км.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q027-b', 'q027', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q027-b', 'ru', '60 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q027-b', 'kk', 'Сағатына 60 км.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q027-c', 'q027', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q027-c', 'ru', '80 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q027-c', 'kk', 'Сағатына 80 км.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q027', 'speed-2', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q028', 'speed', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q028', 'ru', 'Какая максимальная скорость разрешена легковому автомобилю на автомагистрали, если знаками не установлено меньшее ограничение?', 'Вне населённых пунктов легковым автомобилям и мотоциклам разрешено не более 140 км/ч на автомагистралях и не более 110 км/ч на остальных дорогах.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q028', 'kk', 'Егер белгілермен неғұрлым төмен шектеу белгіленбесе, автомагистральда жеңіл автомобильге ең жоғары қандай жылдамдыққа рұқсат етіледі?', 'Елді мекендерден тыс жерлерде жеңіл автомобильдер мен мотоциклдерге автомагистральдарда сағатына 140 км-ден, қалған жолдарда сағатына 110 км-ден аспайтын жылдамдыққа рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q028-a', 'q028', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q028-a', 'ru', '110 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q028-a', 'kk', 'Сағатына 110 км.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q028-b', 'q028', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q028-b', 'ru', '130 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q028-b', 'kk', 'Сағатына 130 км.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q028-c', 'q028', 'c', 3, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q028-c', 'ru', '140 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q028-c', 'kk', 'Сағатына 140 км.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q028', 'speed-3', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q029', 'speed', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q029', 'ru', 'Какова максимальная скорость в жилой зоне и на дворовой территории?', 'В жилых зонах и во дворах пешеходы имеют преимущество, поэтому скорость ограничена 20 км/ч.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q029', 'kk', 'Тұрғын аймақта және аула аумағында ең жоғары жылдамдық қандай?', 'Тұрғын аймақтар мен аулаларда жаяу жүргіншілердің басымдығы бар, сондықтан жылдамдық сағатына 20 км-мен шектелген.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q029-a', 'q029', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q029-a', 'ru', '10 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q029-a', 'kk', 'Сағатына 10 км.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q029-b', 'q029', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q029-b', 'ru', '20 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q029-b', 'kk', 'Сағатына 20 км.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q029-c', 'q029', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q029-c', 'ru', '40 км/ч.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q029-c', 'kk', 'Сағатына 40 км.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q029', 'speed-2', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q030', 'speed', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q030', 'ru', 'Разрешается ли водителю резко тормозить без необходимости?', 'Резкое торможение без необходимости создаёт риск наезда сзади. Оно допустимо только для предотвращения происшествия.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q030', 'kk', 'Жүргізушіге қажеттілік болмаса күрт тежеуге рұқсат етіле ме?', 'Қажетсіз күрт тежеу арттан соғылу қаупін туғызады. Ол тек оқиғаның алдын алу үшін ғана рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q030-a', 'q030', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q030-a', 'ru', 'Разрешается, если сзади никого нет вблизи.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q030-a', 'kk', 'Артта жақын ешкім болмаса, рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q030-b', 'q030', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q030-b', 'ru', 'Запрещается, если это не требуется для предотвращения ДТП.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q030-b', 'kk', 'ЖКО-ның алдын алу үшін қажет болмаса, тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q030-c', 'q030', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q030-c', 'ru', 'Разрешается в любое время.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q030-c', 'kk', 'Кез келген уақытта рұқсат етіледі.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q030', 'speed-4', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q031', 'overtaking', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q031', 'ru', 'В каком из перечисленных мест обгон запрещён?', 'Обгон запрещён на пешеходных переходах, железнодорожных переездах и перед ними, на мостах и в тоннелях, в конце подъёма и на участках с ограниченной видимостью.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q031', 'kk', 'Аталған жерлердің қайсысында басып озуға тыйым салынады?', 'Басып озуға жаяу жүргіншілер өткелдерінде, темір жол өткелдерінде және олардың алдында, көпірлер мен туннельдерде, өрдің соңында және көріну шектеулі учаскелерде тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q031-a', 'q031', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q031-a', 'ru', 'На прямом участке дороги вне населённого пункта с прерывистой разметкой.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q031-a', 'kk', 'Елді мекеннен тыс үзік таңбасы бар жолдың түзу учаскесінде.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q031-b', 'q031', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q031-b', 'ru', 'На пешеходном переходе.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q031-b', 'kk', 'Жаяу жүргіншілер өткелінде.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q031-c', 'q031', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q031-c', 'ru', 'На дороге с тремя полосами в одном направлении.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q031-c', 'kk', 'Бір бағытта үш жолағы бар жолда.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q031', 'overtaking-3', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q032', 'overtaking', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q032', 'ru', 'Вас обгоняют. Что запрещено делать?', 'Водителю обгоняемого транспортного средства запрещено мешать обгону — ускоряться или смещаться к обгоняющему.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q032', 'kk', 'Сізді басып озып жатыр. Не істеуге тыйым салынады?', 'Басып озылатын көлік құралының жүргізушісіне басып озуға кедергі келтіруге — жылдамдықты арттыруға немесе озып бара жатқанға қарай ығысуға тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q032-a', 'q032', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q032-a', 'ru', 'Продолжать движение с прежней скоростью.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q032-a', 'kk', 'Бұрынғы жылдамдықпен жүруді жалғастыру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q032-b', 'q032', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q032-b', 'ru', 'Препятствовать обгону повышением скорости или иными действиями.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q032-b', 'kk', 'Жылдамдықты арттыру немесе өзге әрекеттер арқылы басып озуға кедергі келтіру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q032-c', 'q032', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q032-c', 'ru', 'Держаться правее в своей полосе.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q032-c', 'kk', 'Өз жолағында оң жаққа қарай жүру.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q032', 'overtaking-2', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q033', 'road', '{"type":"road","marking":"broken","scene":"signal-left"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q033', 'overtaking', 'ill-q033', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q033', 'ru', 'Впереди идущий красный автомобиль включил левый указатель поворота. Может ли синий автомобиль начать обгон?', 'Начинать обгон нельзя, если транспортное средство впереди подало сигнал поворота налево: оно может начать поворот и оказаться на вашей траектории.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q033', 'kk', 'Алда келе жатқан қызыл автомобиль солға бұрылу көрсеткішін қосты. Көк автомобиль басып озуды бастай ала ма?', 'Алдағы көлік құралы солға бұрылу сигналын берсе, басып озуды бастауға болмайды: ол бұрыла бастап, сіздің жолыңызда пайда болуы мүмкін.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q033-a', 'q033', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q033-a', 'ru', 'Может, если встречная полоса свободна.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q033-a', 'kk', 'Қарсы жолақ бос болса, бастай алады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q033-b', 'q033', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q033-b', 'ru', 'Не может.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q033-b', 'kk', 'Бастай алмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q033-c', 'q033', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q033-c', 'ru', 'Может, подав звуковой сигнал.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q033-c', 'kk', 'Дыбыстық сигнал беріп, бастай алады.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q033', 'overtaking-1', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q034', 'stop', '{"type":"stop","object":"bus-stop","distance":15}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q034', 'stopping', 'ill-q034', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q034', 'ru', 'Ближе какого расстояния от остановочной площадки маршрутных транспортных средств запрещена остановка?', 'Остановка запрещена на остановочных площадках и ближе 15 м от них (при отсутствии площадки — ближе 15 м от указателя остановки), чтобы не мешать автобусам и пассажирам.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q034', 'kk', 'Бағыттағы көлік құралдарының аялдама алаңынан қандай қашықтықтан жақын тоқтауға тыйым салынады?', 'Автобустар мен жолаушыларға кедергі келтірмеу үшін аялдама алаңдарында және олардан 15 м-ден жақын жерде (алаң болмаса — аялдама көрсеткішінен 15 м-ден жақын жерде) тоқтауға тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q034-a', 'q034', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q034-a', 'ru', '5 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q034-a', 'kk', '5 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q034-b', 'q034', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q034-b', 'ru', '15 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q034-b', 'kk', '15 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q034-c', 'q034', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q034-c', 'ru', '30 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q034-c', 'kk', '30 м.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q034', 'stopping-3', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q035', 'stop', '{"type":"stop","object":"crosswalk","distance":5}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q035', 'stopping', 'ill-q035', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q035', 'ru', 'Ближе какого расстояния перед пешеходным переходом запрещена остановка?', 'Остановка запрещена на переходе и ближе 5 м перед ним: стоящий автомобиль закрывает водителям обзор пешеходов.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q035', 'kk', 'Жаяу жүргіншілер өткелінің алдында қандай қашықтықтан жақын тоқтауға тыйым салынады?', 'Өткелде және оның алдында 5 м-ден жақын жерде тоқтауға тыйым салынады: тұрған автомобиль жүргізушілерге жаяу жүргіншілерді көруге кедергі жасайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q035-a', 'q035', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q035-a', 'ru', '3 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q035-a', 'kk', '3 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q035-b', 'q035', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q035-b', 'ru', '5 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q035-b', 'kk', '5 м.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q035-c', 'q035', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q035-c', 'ru', '10 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q035-c', 'kk', '10 м.');
