INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q036', 'stopping', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q036', 'ru', 'Разрешена ли остановка на мосту или эстакаде?', 'Остановка запрещена на мостах, путепроводах, эстакадах и под ними, в тоннелях и на железнодорожных переездах. При вынужденной остановке включите аварийную сигнализацию и выставьте знак аварийной остановки.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q036', 'kk', 'Көпірде немесе эстакадада тоқтауға рұқсат етіле ме?', 'Көпірлерде, жол өтпелерінде, эстакадаларда және олардың астында, туннельдерде және темір жол өткелдерінде тоқтауға тыйым салынады. Мәжбүрлі тоқтаған кезде авариялық дабылды қосып, авариялық тоқтау белгісін қойыңыз.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q036-a', 'q036', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q036-a', 'ru', 'Разрешена у правого края.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q036-a', 'kk', 'Оң жақ шетінде рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q036-b', 'q036', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q036-b', 'ru', 'Запрещена (кроме вынужденной остановки).');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q036-b', 'kk', 'Тыйым салынады (мәжбүрлі тоқтаудан басқа).');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q036-c', 'q036', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q036-c', 'ru', 'Разрешена не более 5 минут.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q036-c', 'kk', '5 минуттан аспайтын уақытқа рұқсат етіледі.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q036', 'stopping-2', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q036', 'safety-1', 1);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q037', 'crosswalk', '{"type":"crosswalk","pedestrian":"entering"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q037', 'pedestrians', 'ill-q037', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q037', 'ru', 'Пешеход вступил на нерегулируемый пешеходный переход. Как должен поступить водитель синего автомобиля?', 'На нерегулируемом переходе водитель обязан уступить дорогу пешеходам, которые переходят проезжую часть или вступили на неё для перехода.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q037', 'kk', 'Жаяу жүргінші реттелмейтін жаяу жүргіншілер өткеліне шықты. Көк автомобиль жүргізушісі қалай әрекет етуі тиіс?', 'Реттелмейтін өткелде жүргізуші жүру бөлігін кесіп өтіп жатқан немесе өту үшін оған шыққан жаяу жүргіншілерге жол беруге міндетті.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q037-a', 'q037', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q037-a', 'ru', 'Проехать, если пешеход ещё не дошёл до его полосы.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q037-a', 'kk', 'Жаяу жүргінші оның жолағына әлі жетпесе, өту.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q037-b', 'q037', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q037-b', 'ru', 'Уступить дорогу пешеходу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q037-b', 'kk', 'Жаяу жүргіншіге жол беру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q037-c', 'q037', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q037-c', 'ru', 'Подать звуковой сигнал и продолжить движение.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q037-c', 'kk', 'Дыбыстық сигнал беріп, жүруді жалғастыру.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q037', 'pedestrians-2', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-q038', 'crosswalk', '{"type":"crosswalk","pedestrian":"blind"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q038', 'pedestrians', 'ill-q038', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q038', 'ru', 'Незрячий пешеход с белой тростью переходит дорогу вне пешеходного перехода. Как поступить водителю?', 'Незрячим пешеходам, подающим сигнал белой тростью, водитель уступает дорогу во всех случаях — независимо от места перехода.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q038', 'kk', 'Ақ таяғы бар көзі көрмейтін жаяу жүргінші жолды жаяу жүргіншілер өткелінен тыс жерде кесіп өтіп жатыр. Жүргізуші қалай әрекет етуі керек?', 'Ақ таяқпен белгі беретін көзі көрмейтін жаяу жүргіншілерге жүргізуші өту орнына қарамастан барлық жағдайда жол береді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q038-a', 'q038', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q038-a', 'ru', 'Уступить дорогу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q038-a', 'kk', 'Жол беру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q038-b', 'q038', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q038-b', 'ru', 'Продолжить движение: пешеход нарушает правила.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q038-b', 'kk', 'Жүруді жалғастыру: жаяу жүргінші ережені бұзып тұр.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q038-c', 'q038', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q038-c', 'ru', 'Объехать пешехода, не снижая скорости.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q038-c', 'kk', 'Жылдамдықты азайтпай, жаяу жүргіншіні айналып өту.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q038', 'pedestrians-4', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q039', 'pedestrians', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q039', 'ru', 'Как должен двигаться пешеход по обочине вне населённого пункта?', 'Идя навстречу транспорту, пешеход видит приближающиеся автомобили и успевает отойти.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q039', 'kk', 'Елді мекеннен тыс жерде жаяу жүргінші жол жиегімен қалай жүруі тиіс?', 'Көлікке қарсы жүргенде жаяу жүргінші жақындап келе жатқан автомобильдерді көреді және шетке шығып үлгереді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q039-a', 'q039', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q039-a', 'ru', 'По ходу движения транспорта.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q039-a', 'kk', 'Көлік қозғалысы бағытымен.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q039-b', 'q039', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q039-b', 'ru', 'Навстречу движению транспортных средств.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q039-b', 'kk', 'Көлік құралдарының қозғалысына қарсы.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q039-c', 'q039', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q039-c', 'ru', 'По разделительной полосе.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q039-c', 'kk', 'Бөлу жолағымен.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q039', 'pedestrians-1', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q040', 'passengers', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q040', 'ru', 'Как можно перевозить ребёнка 8 лет на переднем сиденье легкового автомобиля?', 'Детей до 12 лет на переднем сиденье перевозят только в детском удерживающем устройстве. На заднем сиденье допускаются и иные средства, позволяющие пристегнуть ребёнка штатным ремнём.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q040', 'kk', '8 жастағы баланы жеңіл автомобильдің алдыңғы орындығында қалай тасымалдауға болады?', '12 жасқа дейінгі балаларды алдыңғы орындықта тек балаларды ұстап тұратын құрылғыда тасымалдайды. Артқы орындықта баланы штаттық белдікпен байлауға мүмкіндік беретін өзге құралдарға да рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q040-a', 'q040', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q040-a', 'ru', 'Пристегнув штатным ремнём безопасности.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q040-a', 'kk', 'Штаттық қауіпсіздік белдігімен байлап.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q040-b', 'q040', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q040-b', 'ru', 'Только в детском удерживающем устройстве.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q040-b', 'kk', 'Тек балаларды ұстап тұратын құрылғыда.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q040-c', 'q040', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q040-c', 'ru', 'На руках у взрослого пассажира.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q040-c', 'kk', 'Ересек жолаушының қолында.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q040', 'passengers-2', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q041', 'passengers', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q041', 'ru', 'Когда и с какой стороны разрешается посадка и высадка пассажиров?', 'Посадка и высадка производятся только после полной остановки и со стороны тротуара или обочины, чтобы пассажиры не оказались на пути других транспортных средств.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q041', 'kk', 'Жолаушыларды отырғызу мен түсіруге қашан және қай жақтан рұқсат етіледі?', 'Жолаушылар басқа көлік құралдарының жолында қалмауы үшін отырғызу мен түсіру тек толық тоқтағаннан кейін және тротуар немесе жол жиегі жағынан жүргізіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q041-a', 'q041', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q041-a', 'ru', 'После полной остановки, со стороны тротуара или обочины.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q041-a', 'kk', 'Толық тоқтағаннан кейін, тротуар немесе жол жиегі жағынан.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q041-b', 'q041', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q041-b', 'ru', 'При скорости не более 5 км/ч с любой стороны.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q041-b', 'kk', 'Сағатына 5 км-ден аспайтын жылдамдықта кез келген жақтан.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q041-c', 'q041', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q041-c', 'ru', 'В любой момент со стороны проезжей части.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q041-c', 'kk', 'Кез келген сәтте жүру бөлігі жағынан.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q041', 'passengers-1', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q042', 'safety', NULL, 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q042', 'ru', 'В каком случае водитель должен включить аварийную сигнализацию?', 'Аварийная сигнализация предупреждает других участников об опасности: её включают при ДТП, при вынужденной остановке в запрещённом месте, при ослеплении и на буксируемом транспортном средстве.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q042', 'kk', 'Жүргізуші қай жағдайда авариялық дабылды қосуы тиіс?', 'Авариялық дабыл басқа қатысушыларды қауіп туралы ескертеді: оны ЖКО кезінде, тыйым салынған жерде мәжбүрлі тоқтағанда, көз шағылысқанда және сүйретілетін көлік құралында қосады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q042-a', 'q042', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q042-a', 'ru', 'При остановке на разрешённом месте, чтобы купить воды.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q042-a', 'kk', 'Су сатып алу үшін рұқсат етілген жерде тоқтағанда.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q042-b', 'q042', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q042-b', 'ru', 'При ДТП, вынужденной остановке там, где остановка запрещена, при ослеплении светом фар.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q042-b', 'kk', 'ЖКО кезінде, тоқтауға тыйым салынған жерде мәжбүрлі тоқтағанда, фара жарығы көзді шағылыстырғанда.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q042-c', 'q042', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q042-c', 'ru', 'Всегда при движении в тёмное время суток.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q042-c', 'kk', 'Тәуліктің қараңғы уақытында жүргенде әрқашан.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q042', 'safety-1', 0);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q043', 'safety', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q043', 'ru', 'Пострадавший без сознания и не дышит. Какое соотношение надавливаний на грудную клетку и вдохов рекомендуется при реанимации взрослого?', 'Современные рекомендации по первой помощи: 30 надавливаний на центр грудной клетки, затем 2 вдоха. Сначала вызовите помощь по номеру 112. Это общие рекомендации, а не текст ПДД.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q043', 'kk', 'Зардап шеккен ессіз және тыныс алмайды. Ересек адамды реанимациялау кезінде кеуде қуысына басу мен үрлеудің қандай арақатынасы ұсынылады?', 'Алғашқы көмек бойынша заманауи ұсынымдар: кеуде қуысының ортасына 30 рет басу, содан кейін 2 рет үрлеу. Алдымен 112 нөмірі бойынша көмек шақырыңыз. Бұл ЖҚЕ мәтіні емес, жалпы ұсынымдар.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q043-a', 'q043', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q043-a', 'ru', '15 надавливаний : 1 вдох.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q043-a', 'kk', '15 басу : 1 үрлеу.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q043-b', 'q043', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q043-b', 'ru', '30 надавливаний : 2 вдоха.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q043-b', 'kk', '30 басу : 2 үрлеу.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q043-c', 'q043', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q043-c', 'ru', '5 надавливаний : 5 вдохов.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q043-c', 'kk', '5 басу : 5 үрлеу.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q043', 'safety-4', 0);
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q043', 'safety-3', 1);
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('q044', 'safety', NULL, 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q044', 'ru', 'Что в первую очередь обязан сделать водитель, причастный к ДТП?', 'Водитель обязан остановиться и обозначить место ДТП, не перемещать предметы, имеющие отношение к происшествию, оказать первую помощь и сообщить в полицию. Покидать место ДТП запрещено.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('q044', 'kk', 'ЖКО-ға қатысы бар жүргізуші ең алдымен не істеуге міндетті?', 'Жүргізуші тоқтап, ЖКО орнын белгілеуге, оқиғаға қатысты заттарды жылжытпауға, алғашқы көмек көрсетуге және полицияға хабарлауға міндетті. ЖКО орнын тастап кетуге тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q044-a', 'q044', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q044-a', 'ru', 'Убрать автомобиль с места происшествия, чтобы не мешать движению.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q044-a', 'kk', 'Қозғалысқа кедергі келтірмеу үшін автомобильді оқиға орнынан алып кету.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q044-b', 'q044', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q044-b', 'ru', 'Немедленно остановиться, включить аварийную сигнализацию, выставить знак аварийной остановки, помочь пострадавшим и сообщить в полицию.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q044-b', 'kk', 'Дереу тоқтап, авариялық дабылды қосу, авариялық тоқтау белгісін қою, зардап шеккендерге көмектесу және полицияға хабарлау.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('q044-c', 'q044', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q044-c', 'ru', 'Сфотографировать место и уехать.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('q044-c', 'kk', 'Орынды суретке түсіріп, кетіп қалу.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('q044', 'driver-6', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-int-equal-w-straight-straight', 'intersection', '{"type":"intersection","cars":[{"from":"s","turn":"straight","color":"blue","label":"A"},{"from":"w","turn":"straight","color":"red","label":"B"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-int-equal-w-straight-straight', 'intersections', 'ill-g-int-equal-w-straight-straight', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-straight-straight', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A едет прямо, B едет прямо. Кто проедет перекрёсток первым?', 'Синий автомобиль A приближается справа от красного автомобиля B, поэтому красный автомобиль B уступает ему дорогу («помеха справа»).');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-straight-straight', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A тура жүреді, B тура жүреді. Қиылыстан кім бірінші өтеді?', 'Көк A автомобилі қызыл B автомобилінің оң жағынан жақындап келеді, сондықтан қызыл B автомобилі оған жол береді («оң жақтан кедергі»).');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-int-equal-w-straight-straight-a', 'g-int-equal-w-straight-straight', 'a', 1, TRUE);
