INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-int-equal-w-straight-straight-a', 'kk', 'Көк A автомобилі');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-int-equal-w-straight-straight-b', 'g-int-equal-w-straight-straight', 'b', 2, FALSE);
