INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-int-equal-w-straight-right', 'intersection', '{"type":"intersection","cars":[{"from":"s","turn":"straight","color":"blue","label":"A"},{"from":"w","turn":"right","color":"red","label":"B"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-int-equal-w-straight-right', 'intersections', 'ill-g-int-equal-w-straight-right', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-straight-right', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A едет прямо, B поворачивает направо. Кто проедет перекрёсток первым?', 'Траектории автомобилей не пересекаются и не сходятся на одной полосе, поэтому уступать дорогу никому не нужно: A и B могут проехать одновременно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-straight-right', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A тура жүреді, B оңға бұрылады. Қиылыстан кім бірінші өтеді?', 'Автомобильдердің жүру жолдары қиылыспайды және бір жолаққа тоғыспайды, сондықтан ешкімге жол берудің қажеті жоқ: A мен B бір мезгілде өте алады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-int-equal-w-straight-right-a', 'g-int-equal-w-straight-right', 'a', 1, FALSE);
