INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-right-straight', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A поворачивает направо, B едет прямо. Кто проедет перекрёсток первым?', 'Синий автомобиль A приближается справа от красного автомобиля B, поэтому красный автомобиль B уступает ему дорогу («помеха справа»).');
