INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-right-right', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A поворачивает направо, B поворачивает направо. Кто проедет перекрёсток первым?', 'Траектории автомобилей не пересекаются и не сходятся на одной полосе, поэтому уступать дорогу никому не нужно: A и B могут проехать одновременно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-right-right', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A оңға бұрылады, B оңға бұрылады. Қиылыстан кім бірінші өтеді?', 'Автомобильдердің жүру жолдары қиылыспайды және бір жолаққа тоғыспайды, сондықтан ешкімге жол берудің қажеті жоқ: A мен B бір мезгілде өте алады.');
