INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-int-equal-w-right-left', 'intersections', 'ill-g-int-equal-w-right-left', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-right-left', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A поворачивает направо, B поворачивает налево. Кто проедет перекрёсток первым?', 'Синий автомобиль A приближается справа от красного автомобиля B, поэтому красный автомобиль B уступает ему дорогу («помеха справа»).');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-w-right-left', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A оңға бұрылады, B солға бұрылады. Қиылыстан кім бірінші өтеді?', 'Көк A автомобилі қызыл B автомобилінің оң жағынан жақындап келеді, сондықтан қызыл B автомобилі оған жол береді («оң жақтан кедергі»).');
