INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-int-equal-n-straight-left', 'intersections', 'ill-g-int-equal-n-straight-left', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-n-straight-left', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A едет прямо, B поворачивает налево. Кто проедет перекрёсток первым?', 'Красный автомобиль B поворачивает налево и должен уступить синему автомобилю A, который движется со встречного направления прямо или направо.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-n-straight-left', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A тура жүреді, B солға бұрылады. Қиылыстан кім бірінші өтеді?', 'Қызыл B автомобилі солға бұрылады және қарсы бағыттан тура немесе оңға жүріп келе жатқан көк A автомобиліне жол беруге тиіс.');
