INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-int-equal-n-right-straight', 'intersections', 'ill-g-int-equal-n-right-straight', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-n-right-straight', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A поворачивает направо, B едет прямо. Кто проедет перекрёсток первым?', 'Траектории автомобилей не пересекаются и не сходятся на одной полосе, поэтому уступать дорогу никому не нужно: A и B могут проехать одновременно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-n-right-straight', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A оңға бұрылады, B тура жүреді. Қиылыстан кім бірінші өтеді?', 'Автомобильдердің жүру жолдары қиылыспайды және бір жолаққа тоғыспайды, сондықтан ешкімге жол берудің қажеті жоқ: A мен B бір мезгілде өте алады.');
