INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-e-straight-right', 'ru', 'Перекрёсток равнозначных дорог, светофора и знаков приоритета нет. A едет прямо, B поворачивает направо. Кто проедет перекрёсток первым?', 'Красный автомобиль B приближается справа от синего автомобиля A, поэтому синий автомобиль A уступает ему дорогу («помеха справа»).');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-e-straight-right', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A тура жүреді, B оңға бұрылады. Қиылыстан кім бірінші өтеді?', 'Қызыл B автомобилі көк A автомобилінің оң жағынан жақындап келеді, сондықтан көк A автомобилі оған жол береді («оң жақтан кедергі»).');
