INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-equal-e-left-left', 'kk', 'Тең маңызды жолдардың қиылысы, бағдаршам және басымдық белгілері жоқ. A солға бұрылады, B солға бұрылады. Қиылыстан кім бірінші өтеді?', 'Қызыл B автомобилі көк A автомобилінің оң жағынан жақындап келеді, сондықтан көк A автомобилі оған жол береді («оң жақтан кедергі»).');
