INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-int-main-ew-w-straight-right', 'intersection', '{"type":"intersection","cars":[{"from":"s","turn":"straight","color":"blue","label":"A"},{"from":"w","turn":"right","color":"red","label":"B"}],"main":"ew","signs":[{"at":"s","sign":"give-way"},{"at":"n","sign":"give-way"}]}');
