INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-n-right-straight', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на второстепенной дороге, красный B — на второстепенной. A поворачивает направо, B едет прямо. Кто проедет перекрёсток первым?', 'Траектории автомобилей не пересекаются и не сходятся на одной полосе, поэтому уступать дорогу никому не нужно: A и B могут проехать одновременно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-n-right-straight', 'kk', 'Тең емес жолдардың қиылысы. Көк A қосалқы жолда, қызыл B — қосалқы жолда. A оңға бұрылады, B тура жүреді. Қиылыстан кім бірінші өтеді?', 'Автомобильдердің жүру жолдары қиылыспайды және бір жолаққа тоғыспайды, сондықтан ешкімге жол берудің қажеті жоқ: A мен B бір мезгілде өте алады.');
