INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-n-right-left', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на второстепенной дороге, красный B — на второстепенной. A поворачивает направо, B поворачивает налево. Кто проедет перекрёсток первым?', 'Оба автомобиля на второстепенной дороге, поэтому между собой они разъезжаются по правилам равнозначного перекрёстка. Красный автомобиль B поворачивает налево и должен уступить синему автомобилю A, который движется со встречного направления прямо или направо.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-n-right-left', 'kk', 'Тең емес жолдардың қиылысы. Көк A қосалқы жолда, қызыл B — қосалқы жолда. A оңға бұрылады, B солға бұрылады. Қиылыстан кім бірінші өтеді?', 'Екі автомобиль де қосалқы жолда, сондықтан өзара тең маңызды қиылыс ережелері бойынша айырылысады. Қызыл B автомобилі солға бұрылады және қарсы бағыттан тура немесе оңға жүріп келе жатқан көк A автомобиліне жол беруге тиіс.');
