INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-int-main-ew-e-straight-straight', 'intersection', '{"type":"intersection","cars":[{"from":"s","turn":"straight","color":"blue","label":"A"},{"from":"e","turn":"straight","color":"red","label":"B"}],"main":"ew","signs":[{"at":"s","sign":"give-way"},{"at":"n","sign":"give-way"}]}');
