INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-e-straight-straight', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на второстепенной дороге, красный B — на главной. A едет прямо, B едет прямо. Кто проедет перекрёсток первым?', 'Синий автомобиль A движется по второстепенной дороге и обязан уступить красному автомобилю B на главной дороге независимо от направления его движения.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-e-straight-straight', 'kk', 'Тең емес жолдардың қиылысы. Көк A қосалқы жолда, қызыл B — басты жолда. A тура жүреді, B тура жүреді. Қиылыстан кім бірінші өтеді?', 'Көк A автомобилі қосалқы жолмен келеді және басты жолдағы қызыл B автомобиліне оның қозғалыс бағытына қарамастан жол беруге міндетті.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-int-main-ew-e-straight-straight-a', 'g-int-main-ew-e-straight-straight', 'a', 1, FALSE);
