INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-e-straight-right', 'kk', 'Тең емес жолдардың қиылысы. Көк A қосалқы жолда, қызыл B — басты жолда. A тура жүреді, B оңға бұрылады. Қиылыстан кім бірінші өтеді?', 'Көк A автомобилі қосалқы жолмен келеді және басты жолдағы қызыл B автомобиліне оның қозғалыс бағытына қарамастан жол беруге міндетті.');
