INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-e-left-left', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на второстепенной дороге, красный B — на главной. A поворачивает налево, B поворачивает налево. Кто проедет перекрёсток первым?', 'Синий автомобиль A движется по второстепенной дороге и обязан уступить красному автомобилю B на главной дороге независимо от направления его движения.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ew-e-left-left', 'kk', 'Тең емес жолдардың қиылысы. Көк A қосалқы жолда, қызыл B — басты жолда. A солға бұрылады, B солға бұрылады. Қиылыстан кім бірінші өтеді?', 'Көк A автомобилі қосалқы жолмен келеді және басты жолдағы қызыл B автомобиліне оның қозғалыс бағытына қарамастан жол беруге міндетті.');
