INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-w-straight-right', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на главной дороге, красный B — на второстепенной. A едет прямо, B поворачивает направо. Кто проедет перекрёсток первым?', 'Траектории автомобилей не пересекаются и не сходятся на одной полосе, поэтому уступать дорогу никому не нужно: A и B могут проехать одновременно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-w-straight-right', 'kk', 'Тең емес жолдардың қиылысы. Көк A басты жолда, қызыл B — қосалқы жолда. A тура жүреді, B оңға бұрылады. Қиылыстан кім бірінші өтеді?', 'Автомобильдердің жүру жолдары қиылыспайды және бір жолаққа тоғыспайды, сондықтан ешкімге жол берудің қажеті жоқ: A мен B бір мезгілде өте алады.');
