INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-n-straight-left', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на главной дороге, красный B — на главной. A едет прямо, B поворачивает налево. Кто проедет перекрёсток первым?', 'Оба автомобиля на главной дороге, поэтому между собой они разъезжаются по правилам равнозначного перекрёстка. Красный автомобиль B поворачивает налево и должен уступить синему автомобилю A, который движется со встречного направления прямо или направо.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-n-straight-left', 'kk', 'Тең емес жолдардың қиылысы. Көк A басты жолда, қызыл B — басты жолда. A тура жүреді, B солға бұрылады. Қиылыстан кім бірінші өтеді?', 'Екі автомобиль де басты жолда, сондықтан өзара тең маңызды қиылыс ережелері бойынша айырылысады. Қызыл B автомобилі солға бұрылады және қарсы бағыттан тура немесе оңға жүріп келе жатқан көк A автомобиліне жол беруге тиіс.');
