INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-e-straight-straight', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на главной дороге, красный B — на второстепенной. A едет прямо, B едет прямо. Кто проедет перекрёсток первым?', 'Красный автомобиль B движется по второстепенной дороге и обязан уступить синему автомобилю A на главной дороге независимо от направления его движения.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-e-straight-straight', 'kk', 'Тең емес жолдардың қиылысы. Көк A басты жолда, қызыл B — қосалқы жолда. A тура жүреді, B тура жүреді. Қиылыстан кім бірінші өтеді?', 'Қызыл B автомобилі қосалқы жолмен келеді және басты жолдағы көк A автомобиліне оның қозғалыс бағытына қарамастан жол беруге міндетті.');
