INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-e-straight-right', 'ru', 'Перекрёсток неравнозначных дорог. Синий A находится на главной дороге, красный B — на второстепенной. A едет прямо, B поворачивает направо. Кто проедет перекрёсток первым?', 'Красный автомобиль B движется по второстепенной дороге и обязан уступить синему автомобилю A на главной дороге независимо от направления его движения.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-main-ns-e-straight-right', 'kk', 'Тең емес жолдардың қиылысы. Көк A басты жолда, қызыл B — қосалқы жолда. A тура жүреді, B оңға бұрылады. Қиылыстан кім бірінші өтеді?', 'Қызыл B автомобилі қосалқы жолмен келеді және басты жолдағы көк A автомобиліне оның қозғалыс бағытына қарамастан жол беруге міндетті.');
