INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-green-n-straight-straight', 'ru', 'Перекрёсток регулируется светофором, обоим автомобилям горит зелёный сигнал. A едет прямо, B едет прямо. Кто проедет перекрёсток первым?', 'Траектории автомобилей не пересекаются и не сходятся на одной полосе, поэтому уступать дорогу никому не нужно: A и B могут проехать одновременно.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-green-n-straight-straight', 'kk', 'Қиылыс бағдаршаммен реттеледі, екі автомобильге де жасыл сигнал жанып тұр. A тура жүреді, B тура жүреді. Қиылыстан кім бірінші өтеді?', 'Автомобильдердің жүру жолдары қиылыспайды және бір жолаққа тоғыспайды, сондықтан ешкімге жол берудің қажеті жоқ: A мен B бір мезгілде өте алады.');
