INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-int-green-n-left-straight', 'ru', 'Перекрёсток регулируется светофором, обоим автомобилям горит зелёный сигнал. A поворачивает налево, B едет прямо. Кто проедет перекрёсток первым?', 'Синий автомобиль A поворачивает налево и должен уступить красному автомобилю B, который движется со встречного направления прямо или направо.');
