INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-ped-straight-e', 'intersection', '{"type":"intersection","light":"green","pedestrian":"e","cars":[{"from":"s","turn":"straight","color":"blue","label":"A"}]}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-ped-straight-e', 'pedestrians', 'ill-g-ped-straight-e', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-straight-e', 'ru', 'Горит зелёный сигнал. Синий автомобиль A едет прямо, пешеход переходит проезжую часть, как показано на схеме. Как должен поступить водитель A?', 'Траектория автомобиля A не проходит через дорогу, которую переходит пешеход, поэтому A может продолжить движение, оставаясь внимательным. Подавать сигнал, чтобы поторопить пешехода, нельзя.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-straight-e', 'kk', 'Жасыл сигнал жанып тұр. Көк A автомобилі тура жүреді, жаяу жүргінші сызбада көрсетілгендей жүру бөлігін кесіп өтіп жатыр. A жүргізушісі қалай әрекет етуі тиіс?', 'A автомобилінің жүру жолы жаяу жүргінші кесіп өтіп жатқан жол арқылы өтпейді, сондықтан A мұқият бола отырып жүруді жалғастыра алады. Жаяу жүргіншіні асықтыру үшін сигнал беруге болмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-ped-straight-e-a', 'g-ped-straight-e', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-straight-e-a', 'ru', 'Уступить дорогу пешеходу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-straight-e-a', 'kk', 'Жаяу жүргіншіге жол беру.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-ped-straight-e-b', 'g-ped-straight-e', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-straight-e-b', 'ru', 'Продолжить движение: пешеход переходит другую дорогу и не мешает его манёвру.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-straight-e-b', 'kk', 'Жүруді жалғастыру: жаяу жүргінші басқа жолды кесіп өтіп жатыр және оның маневріне кедергі жасамайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-ped-straight-e-c', 'g-ped-straight-e', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-straight-e-c', 'ru', 'Подать звуковой сигнал, чтобы пешеход ускорился.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-straight-e-c', 'kk', 'Жаяу жүргінші жылдамдауы үшін дыбыстық сигнал беру.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('g-ped-straight-e', 'intersections-1', 0);
