INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-right-e', 'ru', 'Горит зелёный сигнал. Синий автомобиль A поворачивает направо, пешеход переходит проезжую часть, как показано на схеме. Как должен поступить водитель A?', 'При повороте водитель обязан уступить дорогу пешеходам, пересекающим проезжую часть, на которую он поворачивает, даже при зелёном сигнале.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-right-e', 'kk', 'Жасыл сигнал жанып тұр. Көк A автомобилі оңға бұрылады, жаяу жүргінші сызбада көрсетілгендей жүру бөлігін кесіп өтіп жатыр. A жүргізушісі қалай әрекет етуі тиіс?', 'Бұрылған кезде жүргізуші жасыл сигнал болса да, өзі бұрылатын жүру бөлігін кесіп өтіп жатқан жаяу жүргіншілерге жол беруге міндетті.');
