INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-ped-left-e', 'pedestrians', 'ill-g-ped-left-e', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-left-e', 'ru', 'Горит зелёный сигнал. Синий автомобиль A поворачивает налево, пешеход переходит проезжую часть, как показано на схеме. Как должен поступить водитель A?', 'Траектория автомобиля A не проходит через дорогу, которую переходит пешеход, поэтому A может продолжить движение, оставаясь внимательным. Подавать сигнал, чтобы поторопить пешехода, нельзя.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-left-e', 'kk', 'Жасыл сигнал жанып тұр. Көк A автомобилі солға бұрылады, жаяу жүргінші сызбада көрсетілгендей жүру бөлігін кесіп өтіп жатыр. A жүргізушісі қалай әрекет етуі тиіс?', 'A автомобилінің жүру жолы жаяу жүргінші кесіп өтіп жатқан жол арқылы өтпейді, сондықтан A мұқият бола отырып жүруді жалғастыра алады. Жаяу жүргіншіні асықтыру үшін сигнал беруге болмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-ped-left-e-a', 'g-ped-left-e', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-left-e-a', 'ru', 'Уступить дорогу пешеходу.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-left-e-a', 'kk', 'Жаяу жүргіншіге жол беру.');
