INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-left-e-b', 'ru', 'Продолжить движение: пешеход переходит другую дорогу и не мешает его манёвру.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-ped-left-e-b', 'kk', 'Жүруді жалғастыру: жаяу жүргінші басқа жолды кесіп өтіп жатыр және оның маневріне кедергі жасамайды.');
