INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-ped-left-w', 'kk', 'Жасыл сигнал жанып тұр. Көк A автомобилі солға бұрылады, жаяу жүргінші сызбада көрсетілгендей жүру бөлігін кесіп өтіп жатыр. A жүргізушісі қалай әрекет етуі тиіс?', 'Бұрылған кезде жүргізуші жасыл сигнал болса да, өзі бұрылатын жүру бөлігін кесіп өтіп жатқан жаяу жүргіншілерге жол беруге міндетті.');
