INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-speed-town', 'ru', 'С какой максимальной скоростью разрешено двигаться легковому автомобилю в населённом пункте?', 'Если знаками не установлено иное, легковому автомобилю в населённом пункте разрешено не более 60 км/ч.');
