INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-speed-road-70', 'kk', 'Жеңіл автомобильге ең жоғары жылдамдықты сағатына 70 км-ге шектеу белгісі орнатылған елді мекеннен тыс жерде ең жоғары қандай жылдамдықпен жүруге рұқсат етіледі?', 'Ең жоғары жылдамдықты шектеу белгісі онда көрсетілгеннен жоғары жылдамдықпен жүруге тыйым салады: мұнда сағатына 70 км-ден аспайды.');
