INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-light-red', 'light', '{"type":"light","state":"red"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-light-red', 'signals', 'ill-g-light-red', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-red', 'ru', 'Разрешено ли водителю начать движение через перекрёсток при таком сигнале светофора?', 'Красный сигнал запрещает движение.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-red', 'kk', 'Бағдаршамның осындай сигналында жүргізушіге қиылыс арқылы қозғалысты бастауға рұқсат етіле ме?', 'Қызыл сигнал қозғалысқа тыйым салады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-red-a', 'g-light-red', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-a', 'ru', 'Да, разрешено.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-a', 'kk', 'Иә, рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-red-b', 'g-light-red', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-b', 'ru', 'Нет, запрещено.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-b', 'kk', 'Жоқ, тыйым салынады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-red-c', 'g-light-red', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-c', 'ru', 'Только в направлении стрелки, уступив дорогу транспорту с других направлений.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-c', 'kk', 'Тек бағдарше бағытында, басқа бағыттардан келе жатқан көлікке жол беріп.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-red-d', 'g-light-red', 'd', 4, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-d', 'ru', 'Да, руководствуясь правилами проезда нерегулируемых перекрёстков и знаками приоритета.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-d', 'kk', 'Иә, реттелмейтін қиылыстардан өту ережелерін және басымдық белгілерін басшылыққа ала отырып.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('g-light-red', 'signals-4', 0);
INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-light-yellow', 'light', '{"type":"light","state":"yellow"}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-light-yellow', 'signals', 'ill-g-light-yellow', 2);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-yellow', 'ru', 'Разрешено ли водителю начать движение через перекрёсток при таком сигнале светофора?', 'Жёлтый сигнал запрещает движение; продолжить движение можно только тому, кто не может остановиться без экстренного торможения, а начинать движение нельзя.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-yellow', 'kk', 'Бағдаршамның осындай сигналында жүргізушіге қиылыс арқылы қозғалысты бастауға рұқсат етіле ме?', 'Сары сигнал қозғалысқа тыйым салады; шұғыл тежеусіз тоқтай алмайтын жүргізуші ғана жүруді жалғастыра алады, ал қозғалысты бастауға болмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-yellow-a', 'g-light-yellow', 'a', 1, FALSE);
