INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-red-yellow', 'ru', 'Разрешено ли водителю начать движение через перекрёсток при таком сигнале светофора?', 'Красный с жёлтым — запрещающий сигнал: он лишь предупреждает, что скоро включится зелёный.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-red-yellow', 'kk', 'Бағдаршамның осындай сигналында жүргізушіге қиылыс арқылы қозғалысты бастауға рұқсат етіле ме?', 'Қызыл мен сары — тыйым салатын сигнал: ол тек жақында жасыл қосылатынын ескертеді.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-red-yellow-a', 'g-light-red-yellow', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-yellow-a', 'ru', 'Да, разрешено.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-yellow-a', 'kk', 'Иә, рұқсат етіледі.');
