INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-yellow-c', 'ru', 'Только в направлении стрелки, уступив дорогу транспорту с других направлений.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-yellow-c', 'kk', 'Тек бағдарше бағытында, басқа бағыттардан келе жатқан көлікке жол беріп.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-light-red-yellow-d', 'g-light-red-yellow', 'd', 4, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-light-red-yellow-d', 'ru', 'Да, руководствуясь правилами проезда нерегулируемых перекрёстков и знаками приоритета.');
