INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-light-red-arrow-right', 'kk', 'Бағдаршамның осындай сигналында жүргізушіге қиылыс арқылы қозғалысты бастауға рұқсат етіле ме?', 'Қосымша секциядағы жасыл бағдарше тек өз бағытында қозғалуға рұқсат береді, бұл ретте басқа бағыттардан келе жатқан көлікке жол беру керек.');
