INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-stop-crosswalk-2', 'stop', '{"type":"stop","object":"crosswalk","distance":2}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-stop-crosswalk-2', 'stopping', 'ill-g-stop-crosswalk-2', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-stop-crosswalk-2', 'ru', 'Водитель остановился в 2 м перед пешеходным переходом. Разрешена ли такая остановка?', 'Остановка запрещена ближе 5 м перед пешеходным переходом. 2 м меньше 5 м, поэтому остановка запрещена. Аварийная сигнализация не делает запрещённую остановку разрешённой.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-stop-crosswalk-2', 'kk', 'Жүргізуші жаяу жүргіншілер өткелінің алдында 2 м жерде тоқтады. Мұндай тоқтауға рұқсат етіле ме?', 'Жаяу жүргіншілер өткелінің алдында 5 м-ден жақын тоқтауға тыйым салынады. 2 м 5 м-ден аз, сондықтан тоқтауға тыйым салынады. Авариялық дабыл тыйым салынған тоқтауды рұқсат етілгенге айналдырмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-stop-crosswalk-2-a', 'g-stop-crosswalk-2', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-crosswalk-2-a', 'ru', 'Разрешена.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-crosswalk-2-a', 'kk', 'Рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-stop-crosswalk-2-b', 'g-stop-crosswalk-2', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-crosswalk-2-b', 'ru', 'Запрещена: слишком близко.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-crosswalk-2-b', 'kk', 'Тыйым салынады: тым жақын.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-stop-crosswalk-2-c', 'g-stop-crosswalk-2', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-crosswalk-2-c', 'ru', 'Разрешена только с включённой аварийной сигнализацией.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-crosswalk-2-c', 'kk', 'Тек авариялық дабыл қосулы болғанда рұқсат етіледі.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('g-stop-crosswalk-2', 'stopping-3', 0);
