INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-stop-bus-stop-14', 'ru', 'Водитель остановился в 14 м перед остановочной площадкой автобуса. Разрешена ли такая остановка?', 'Остановка запрещена ближе 15 м от остановочной площадки маршрутных транспортных средств. 14 м меньше 15 м, поэтому остановка запрещена. Аварийная сигнализация не делает запрещённую остановку разрешённой.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-stop-bus-stop-14', 'kk', 'Жүргізуші автобус аялдамасы алаңының алдында 14 м жерде тоқтады. Мұндай тоқтауға рұқсат етіле ме?', 'Бағыттағы көлік құралдарының аялдама алаңынан 15 м-ден жақын тоқтауға тыйым салынады. 14 м 15 м-ден аз, сондықтан тоқтауға тыйым салынады. Авариялық дабыл тыйым салынған тоқтауды рұқсат етілгенге айналдырмайды.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-stop-bus-stop-14-a', 'g-stop-bus-stop-14', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-bus-stop-14-a', 'ru', 'Разрешена.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-bus-stop-14-a', 'kk', 'Рұқсат етіледі.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-stop-bus-stop-14-b', 'g-stop-bus-stop-14', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-bus-stop-14-b', 'ru', 'Запрещена: слишком близко.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-bus-stop-14-b', 'kk', 'Тыйым салынады: тым жақын.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-stop-bus-stop-14-c', 'g-stop-bus-stop-14', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-stop-bus-stop-14-c', 'ru', 'Разрешена только с включённой аварийной сигнализацией.');
