INSERT INTO illustrations (id, kind, params_json) VALUES ('ill-g-triangle-inside-8', 'triangle', '{"type":"triangle","area":"inside","distance":8,"exact":true}');
INSERT INTO questions (id, topic_id, illustration_id, difficulty) VALUES ('g-triangle-inside-8', 'driver', 'ill-g-triangle-inside-8', 1);
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-triangle-inside-8', 'ru', 'Автомобиль вынужденно остановился в населённом пункте. Водитель выставил знак аварийной остановки в 8 м от автомобиля. Достаточно ли этого расстояния?', 'Знак аварийной остановки выставляют не ближе 15 м от автомобиля в населённом пункте и не ближе 30 м вне населённого пункта. Здесь требуется не менее 15 м, а выставлено 8 м.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-triangle-inside-8', 'kk', 'Автомобиль елді мекенде мәжбүрлі тоқтады. Жүргізуші авариялық тоқтау белгісін автомобильден 8 м жерге қойды. Бұл қашықтық жеткілікті ме?', 'Авариялық тоқтау белгісі елді мекенде автомобильден кемінде 15 м, елді мекеннен тыс жерде кемінде 30 м қашықтықта қойылады. Мұнда кемінде 15 м қажет, ал 8 м жерге қойылған.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-triangle-inside-8-a', 'g-triangle-inside-8', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-inside-8-a', 'ru', 'Достаточно.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-inside-8-a', 'kk', 'Жеткілікті.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-triangle-inside-8-b', 'g-triangle-inside-8', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-inside-8-b', 'ru', 'Недостаточно: нужно не менее 15 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-inside-8-b', 'kk', 'Жеткіліксіз: кемінде 15 м қажет.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-triangle-inside-8-c', 'g-triangle-inside-8', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-inside-8-c', 'ru', 'Недостаточно: нужно не менее 30 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-inside-8-c', 'kk', 'Жеткіліксіз: кемінде 30 м қажет.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('g-triangle-inside-8', 'safety-2', 0);
