INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-triangle-inside-35', 'kk', 'Автомобиль елді мекенде мәжбүрлі тоқтады. Жүргізуші авариялық тоқтау белгісін автомобильден 35 м жерге қойды. Бұл қашықтық жеткілікті ме?', 'Авариялық тоқтау белгісі елді мекенде автомобильден кемінде 15 м, елді мекеннен тыс жерде кемінде 30 м қашықтықта қойылады. Мұнда кемінде 15 м қажет, ал 35 м жерге қойылған.');
