INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-triangle-outside-40-a', 'g-triangle-outside-40', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-outside-40-a', 'ru', 'Достаточно.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-outside-40-a', 'kk', 'Жеткілікті.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-triangle-outside-40-b', 'g-triangle-outside-40', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-outside-40-b', 'ru', 'Недостаточно: нужно не менее 15 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-outside-40-b', 'kk', 'Жеткіліксіз: кемінде 15 м қажет.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-triangle-outside-40-c', 'g-triangle-outside-40', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-outside-40-c', 'ru', 'Недостаточно: нужно не менее 30 м.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-triangle-outside-40-c', 'kk', 'Жеткіліксіз: кемінде 30 м қажет.');
INSERT INTO question_rule_refs (question_id, item_id, sort_order) VALUES ('g-triangle-outside-40', 'safety-2', 0);
