INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-child-front-3', 'ru', 'Как допускается перевозить ребёнка 3 лет на переднем сиденье легкового автомобиля, оборудованного ремнями безопасности?', 'На переднем сиденье детей до 12 лет перевозят только в детском удерживающем устройстве.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-child-front-3', 'kk', 'Қауіпсіздік белдіктерімен жабдықталған жеңіл автомобильдің алдыңғы орындықта 3 жастағы баланы қалай тасымалдауға рұқсат етіледі?', 'Алдыңғы орындықта 12 жасқа дейінгі балалар тек балаларды ұстап тұратын құрылғыда тасымалданады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-child-front-3-a', 'g-child-front-3', 'a', 1, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-front-3-a', 'ru', 'Только в детском удерживающем устройстве.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-front-3-a', 'kk', 'Тек балаларды ұстап тұратын құрылғыда.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-child-front-3-b', 'g-child-front-3', 'b', 2, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-front-3-b', 'ru', 'В детском удерживающем устройстве или с иными средствами, позволяющими пристегнуть ребёнка штатным ремнём.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-front-3-b', 'kk', 'Балаларды ұстап тұратын құрылғыда немесе баланы штаттық белдікпен байлауға мүмкіндік беретін өзге құралдармен.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-child-front-3-c', 'g-child-front-3', 'c', 3, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-front-3-c', 'ru', 'Пристегнув штатным ремнём безопасности, как взрослого пассажира.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-front-3-c', 'kk', 'Ересек жолаушы сияқты штаттық қауіпсіздік белдігімен байлап.');
