INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-child-rear-3', 'ru', 'Как допускается перевозить ребёнка 3 лет на заднем сиденье легкового автомобиля, оборудованного ремнями безопасности?', 'На заднем сиденье детей до 12 лет перевозят в детском удерживающем устройстве или с иными средствами, позволяющими пристегнуть их штатными ремнями.');
INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-child-rear-3', 'kk', 'Қауіпсіздік белдіктерімен жабдықталған жеңіл автомобильдің артқы орындықта 3 жастағы баланы қалай тасымалдауға рұқсат етіледі?', 'Артқы орындықта 12 жасқа дейінгі балалар ұстап тұратын құрылғыда немесе оларды штаттық белдіктермен байлауға мүмкіндік беретін өзге құралдармен тасымалданады.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-child-rear-3-a', 'g-child-rear-3', 'a', 1, FALSE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-rear-3-a', 'ru', 'Только в детском удерживающем устройстве.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-rear-3-a', 'kk', 'Тек балаларды ұстап тұратын құрылғыда.');
INSERT INTO answer_options (id, question_id, label, sort_order, is_correct) VALUES ('g-child-rear-3-b', 'g-child-rear-3', 'b', 2, TRUE);
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-rear-3-b', 'ru', 'В детском удерживающем устройстве или с иными средствами, позволяющими пристегнуть ребёнка штатным ремнём.');
INSERT INTO answer_option_translations (option_id, lang, body) VALUES ('g-child-rear-3-b', 'kk', 'Балаларды ұстап тұратын құрылғыда немесе баланы штаттық белдікпен байлауға мүмкіндік беретін өзге құралдармен.');
