INSERT INTO question_translations (question_id, lang, body, explanation) VALUES ('g-child-rear-13', 'ru', 'Как допускается перевозить ребёнка 13 лет на заднем сиденье легкового автомобиля, оборудованного ремнями безопасности?', 'Требования о детских удерживающих устройствах касаются детей до 12 лет. Ребёнок старше 12 лет пристёгивается штатным ремнём безопасности.');
